/* Session 3: SQL and Databases.
   Ported from the sekher-learning SQL module. Sections: introduction, tables, fundamentals, joins,
   advanced SQL, indexing and performance, transactions and design. */
(() => {
  const { block, list, callout, task } = Ops.h;
  const subs = [];

  /* ---------- 3.1 Introduction ---------- */
  subs.push({
    key: 'introduction', title: 'Introduction', lead: 'What SQL is, why it was created, who made it, and how databases work, before writing any query.',
    blocks: [
      block('Overview', '', `<div class="callout green"><div class="callout-title">Learn the thinking before the commands</div><p>This page explains <strong>why SQL exists</strong>, who created it and how a database works. No queries yet.</p></div>`),
      block('What is SQL?', '', `<p>SQL stands for <strong>Structured Query Language</strong>. It is the language we use to talk to a database: what we want to read, what we want to save, and how we want to change or organize it.</p><p>Imagine <strong>AddressBox</strong>, a real-estate app. It must remember users and phone numbers, properties and prices, owners, customer inquiries, messages and notifications. All of that lives in a database.</p><figure class="figure" data-fig="flow" data-args="{&quot;items&quot;:[{&quot;t&quot;:&quot;AddressBox&quot;,&quot;s&quot;:&quot;Backend API&quot;,&quot;c&quot;:&quot;green&quot;},{&quot;t&quot;:&quot;SQL&quot;},{&quot;t&quot;:&quot;Database&quot;,&quot;s&quot;:&quot;e.g. PostgreSQL&quot;,&quot;c&quot;:&quot;gray&quot;}],&quot;opts&quot;:{&quot;bidir&quot;:true,&quot;w&quot;:150}}"><figcaption>The backend sends SQL; the database stores and returns the data.</figcaption></figure><p>The backend might need to:</p><ul><li>Find all properties in Ahmedabad.</li><li>Save a new user's details.</li><li>Change a property's price.</li><li>Delete an inquiry that should no longer exist.</li></ul><table class="tbl"><thead><tr><th>Term</th><th>What it is</th></tr></thead><tbody><tr><td><strong>SQL</strong></td><td>The language</td></tr><tr><td><strong>PostgreSQL / MySQL</strong></td><td>Database management systems that understand SQL</td></tr><tr><td><strong>Database</strong></td><td>The organized collection of stored information</td></tr><tr><td><strong>Backend</strong></td><td>The application code that handles requests and talks to the database</td></tr></tbody></table>`, '1'),
      block('Why was SQL created?', '', `<p>Imagine a company storing one million customers in text files or spreadsheets. Problems appear quickly:</p><ol><li>Finding one customer among millions is slow and hard.</li><li>Two customers can accidentally get the same ID.</li><li>Different employees update the same information incorrectly.</li><li>A computer crash can interrupt a data update halfway.</li><li>Finding customers who match several conditions gets complicated.</li></ol><p>People needed a better way to store, retrieve and manage large amounts of structured information. The answer was <strong>relational databases</strong>: organize data into related tables, and give people a language to work with them.</p>`, '2'),
      block('Who created SQL?', '', `<table class="tbl"><thead><tr><th>Who</th><th>Contribution</th></tr></thead><tbody><tr><td><strong>Edgar F. Codd</strong> (1970)</td><td>Proposed the relational model: organizing data into relations, which inspired relational databases.</td></tr><tr><td><strong>Donald Chamberlin &amp; Raymond Boyce</strong> (IBM, 1970s)</td><td>Developed SEQUEL, the predecessor of SQL, to work with relational data.</td></tr></tbody></table><p>No single person wrote all of SQL. Researchers, database companies and standards bodies improved it over time. <strong>ANSI and ISO</strong> standardized it, so different databases share a common language.</p>`, '3'),
      block('Why is it called a relational database?', '', `<p>Data is stored in <strong>tables</strong> that connect through <strong>relationships</strong>. Take an online shop:</p><div style="display:flex;flex-wrap:wrap;gap:24px"><div><strong>Customers</strong><table class="tbl"><thead><tr><th>customer_id</th><th>name</th></tr></thead><tbody><tr><td>101</td><td>Rahul</td></tr><tr><td>102</td><td>Amit</td></tr></tbody></table></div><div><strong>Orders</strong><table class="tbl"><thead><tr><th>order_id</th><th>customer_id</th><th>amount</th></tr></thead><tbody><tr><td>501</td><td>101</td><td>₹2,000</td></tr><tr><td>502</td><td>101</td><td>₹500</td></tr><tr><td>503</td><td>102</td><td>₹1,200</td></tr></tbody></table></div></div><p><code>customer_id</code> in Orders points to the customer who placed the order. Rahul's name is <em>not</em> repeated in every order; each order just refers to <code>customer_id = 101</code>.</p><p>That lets us answer: who placed order 501, how many orders Rahul placed, how much he spent, and which customers have not ordered at all.</p>`, '4'),
      block('Database vs Excel sheet', '', `<table class="tbl"><thead><tr><th>Feature</th><th>Spreadsheet</th><th>Relational database</th></tr></thead><tbody><tr><td>Store rows and columns</td><td>Yes</td><td>Yes</td></tr><tr><td>Connect related data</td><td>Possible, often manual</td><td>Built-in relationships</td></tr><tr><td>Many concurrent users</td><td>Limited</td><td>Designed for it</td></tr><tr><td>Enforce data rules</td><td>Some support</td><td>Strong constraints and validation</td></tr><tr><td>Transactions</td><td>Limited</td><td>Built-in</td></tr><tr><td>Search and combine large data</td><td>Gets cumbersome</td><td>Designed for efficient querying</td></tr></tbody></table><p>With 500 salespeople using a CRM at once, one person's update must not overwrite another's work, and searches must stay fast and consistent. That is where a real database becomes essential.</p>`, '5'),
      block('What happens when you use SQL?', '', `<p>A customer searches for properties in Ahmedabad:</p><figure class="figure" data-fig="flow" data-args="{&quot;items&quot;:[{&quot;t&quot;:&quot;User&quot;,&quot;s&quot;:&quot;searches&quot;},{&quot;t&quot;:&quot;Backend&quot;,&quot;s&quot;:&quot;business rules&quot;,&quot;c&quot;:&quot;amber&quot;},{&quot;t&quot;:&quot;Database&quot;,&quot;s&quot;:&quot;runs the query&quot;,&quot;c&quot;:&quot;gray&quot;},{&quot;t&quot;:&quot;Results&quot;,&quot;s&quot;:&quot;to backend&quot;},{&quot;t&quot;:&quot;User&quot;,&quot;s&quot;:&quot;sees properties&quot;,&quot;c&quot;:&quot;green&quot;}],&quot;opts&quot;:{&quot;w&quot;:128,&quot;gap&quot;:32}}"><figcaption>The backend builds the database operation; the database executes it.</figcaption></figure><p>The database does not magically know what the user wants. In NestJS this may be raw SQL or an ORM such as Sequelize, Prisma or TypeORM, which generates SQL for you.</p>`, '6'),
      block('Why different database technologies?', '', `<table class="tbl"><thead><tr><th>Database</th><th>What it is</th></tr></thead><tbody><tr><td><strong>PostgreSQL</strong></td><td>Relational. SQL, relationships, transactions, indexes, advanced types. Vector search via the pgvector extension.</td></tr><tr><td><strong>MySQL</strong></td><td>Relational. Common for web apps and business systems.</td></tr><tr><td><strong>MongoDB</strong></td><td>Document database. Stores JSON-like documents instead of relational tables.</td></tr><tr><td><strong>SQLite</strong></td><td>Small relational database stored in a single file; good for local and embedded use.</td></tr></tbody></table><p>Different apps need different things: relationships, consistency, flexible structure, search speed, scale. SQL is not a database; PostgreSQL and MySQL implement it, while MongoDB mainly uses a different query interface.</p>`, '7'),
      block('What is inside a database?', '', `<table class="tbl"><thead><tr><th>Component</th><th>Job</th></tr></thead><tbody><tr><td>Parser</td><td>Checks the instruction has valid syntax</td></tr><tr><td>Query planner / optimizer</td><td>Chooses an efficient way to get or change the data</td></tr><tr><td>Execution engine</td><td>Carries out the chosen plan</td></tr><tr><td>Storage engine</td><td>Manages how data is stored and retrieved</td></tr><tr><td>Transactions &amp; concurrency</td><td>Keep data correct when operations overlap</td></tr><tr><td>Indexes</td><td>Faster ways to locate records</td></tr><tr><td>Logging &amp; recovery</td><td>Survive crashes and keep data durable</td></tr></tbody></table><p>With 20 million property records, finding one should not mean reading every row; an index helps. The database also copes with a crash mid-update and two users editing the same record. That is why database engineering is a whole field.</p>`, '8'),
      block('The four things a database must do (CRUD)', '', `<table class="tbl"><thead><tr><th>Operation</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td><strong>C</strong>reate</td><td>Save new data</td><td>A new user or inquiry</td></tr><tr><td><strong>R</strong>ead</td><td>Find data</td><td>Search properties</td></tr><tr><td><strong>U</strong>pdate</td><td>Change data</td><td>A price or inquiry status</td></tr><tr><td><strong>D</strong>elete</td><td>Remove data, if retention rules allow</td><td>Remove an old record</td></tr></tbody></table><p>The syntax comes later. For now, know what each one is for.</p>`, '9'),
      block('The takeaway', '', `<p>SQL exists because applications need a <strong>reliable, structured and efficient</strong> way to work with data. You say <em>what</em> you want; the database decides <em>how</em>, while handling storage, speed, consistency and concurrent access.</p><p>For a 1 to 2 year SDE role, think beyond memorizing commands. Be able to reason about:</p><ul><li>How data should be organized.</li><li>How tables relate to each other.</li><li>How to retrieve the right information.</li><li>How to prevent incorrect or inconsistent data.</li><li>How databases run operations efficiently.</li><li>How applications safely read and update data.</li></ul><div class="callout amber"><div class="callout-title">Next topic</div><p>How a database is structured: tables, rows, columns, data types, primary keys, foreign keys, constraints and relationships.</p></div>`, '10'),
      block('Key points', '', list(["SQL is the language; PostgreSQL and MySQL are databases that understand it.","SQL exists because files and spreadsheets break down at scale: slow search, duplicate IDs, bad concurrent updates, crashes.","Relational = tables connected by keys, so data is stored once and referenced.","Codd proposed the relational model (1970); Chamberlin and Boyce at IBM built SEQUEL, which became SQL.","A database is more than a file: parser, planner, storage engine, transactions, indexes and recovery.","Everything is CRUD: Create, Read, Update, Delete."]) + callout('amber', 'Tip', 'You say what data you want; the database decides how to get it.')),
      block('Quick note: SQL in one minute', '', `<p><strong>SQL</strong> is the language. <strong>PostgreSQL/MySQL</strong> are the databases. The <strong>backend</strong> sends SQL; the database stores and returns data.</p><p>Databases beat files and spreadsheets on: fast search, unique IDs, safe concurrent updates, crash recovery, enforced rules.</p><p><strong>Relational</strong> = tables connected by keys. <strong>CRUD</strong> = Create, Read, Update, Delete.</p>`),
      block('Quick note: things not to say in an interview', '', `<ul><li>"SQL is a database." It is a language.</li><li>"One person invented SQL." Codd, Chamberlin, Boyce and standards bodies all contributed.</li><li>"A database is just a file." It has a planner, indexes, transactions and recovery.</li><li>"A database is just a bigger Excel." Constraints, concurrency and transactions are the difference.</li></ul>`),
      task(1, '1. What is SQL?', 'Answer it in your own words, then check.', '', `<h4>Simple explanation</h4><p>SQL (Structured Query Language) is the language used to communicate with a relational database: to read, save, change and organize data.</p><h4>Do not mix these up</h4><ul><li><strong>SQL</strong>: the language</li><li><strong>PostgreSQL / MySQL</strong>: database systems that understand SQL</li><li><strong>Database</strong>: the stored, organized data</li><li><strong>Backend</strong>: code that receives requests and talks to the database</li></ul><div class="callout green"><div class="callout-title">Interview answer</div><p>SQL is the standard language for working with relational databases. The backend uses it to ask the database for data or to store and change data.</p></div>`),
      task(2, '2. Why was SQL created? What problem does it solve?', 'Answer it in your own words, then check.', '', `<p>Before databases, companies used text files and spreadsheets. At scale these fail:</p><ul><li>Finding one record among millions is hard</li><li>Duplicate IDs</li><li>Conflicting updates from different people</li><li>Crashes leave updates half-done</li><li>Multi-condition searches are complicated</li></ul><div class="callout green"><div class="callout-title">Interview answer</div><p>Relational databases and SQL give a structured, efficient and consistent way to store, find and change large amounts of data, even with many users at once.</p></div>`),
      task(3, '3. Who created SQL?', 'Answer it in your own words, then check.', '', `<ul><li><strong>Edgar F. Codd</strong> proposed the relational model in 1970.</li><li><strong>Donald Chamberlin and Raymond Boyce</strong> (IBM, 1970s) developed SEQUEL, the predecessor of SQL.</li></ul><p>SQL was then improved by many companies and standardized by <strong>ANSI and ISO</strong>.</p><div class="callout amber"><div class="callout-title">Remember</div><p>Do not say one person invented all of SQL.</p></div>`),
      task(4, '4. What is a relational database?', 'Answer it in your own words, then check.', '', `<p>A database that stores data in tables and connects them through relationships. For example, an <code>orders</code> table holds a <code>customer_id</code> that points to a row in <code>customers</code>.</p><p>The customer's name is stored once, not repeated in every order. This avoids duplication and lets you ask questions across tables, such as how many orders a customer placed.</p><div class="callout green"><div class="callout-title">Interview answer</div><p>A relational database organizes data into related tables. Rows in one table refer to rows in another using keys, so data is stored once and combined when needed.</p></div>`),
      task(5, '5. How is a database different from an Excel sheet?', 'Answer it in your own words, then check.', '', `<p>Both show rows and columns. A database adds:</p><ul><li>Built-in relationships between tables</li><li>Safe access for many concurrent users</li><li>Strong constraints and validation</li><li>Transactions</li><li>Efficient search over very large data</li></ul><div class="callout green"><div class="callout-title">Interview answer</div><p>A spreadsheet stores data. A database also protects it: it enforces rules, handles many users at once, supports transactions and searches large data efficiently.</p></div>`),
      task(6, '6. How does an application use SQL?', 'Answer it in your own words, then check.', '', `<ol><li>The user sends a request (for example, search properties in Ahmedabad).</li><li>The backend receives it and applies business rules.</li><li>The backend builds a database operation.</li><li>The database executes it and returns results.</li><li>The backend sends the response to the user.</li></ol><p>In NestJS this can be raw SQL, or an ORM such as Sequelize, Prisma or TypeORM that generates the SQL.</p>`),
      task(7, '7. PostgreSQL vs MySQL vs MongoDB vs SQLite: why so many?', 'Answer it in your own words, then check.', '', `<ul><li><strong>PostgreSQL</strong>: relational, rich features, extensions such as pgvector</li><li><strong>MySQL</strong>: relational, popular for web apps</li><li><strong>MongoDB</strong>: stores JSON-like documents, flexible structure</li><li><strong>SQLite</strong>: relational, single-file, lightweight</li></ul><div class="callout green"><div class="callout-title">Interview answer</div><p>Different apps need different trade-offs: relationships and consistency, flexible documents, speed, scale or simplicity. SQL is a language, not a database; PostgreSQL and MySQL implement it.</p></div>`),
      task(8, '8. What happens inside a database when it receives a query?', 'Answer it in your own words, then check.', '', `<ol><li>The <strong>parser</strong> checks the syntax.</li><li>The <strong>planner/optimizer</strong> picks an efficient plan (for example, using an index).</li><li>The <strong>execution engine</strong> runs the plan.</li><li>The <strong>storage engine</strong> reads or writes the data.</li><li>Transaction, concurrency and logging systems keep it correct and recoverable.</li></ol><div class="callout amber"><div class="callout-title">Remember</div><p>Do not say a database is "just a file with rows". Indexes, transactions and recovery are what make it a database.</p></div>`),
      task(9, '9. What is CRUD?', 'Answer it in your own words, then check.', '', `<p><strong>C</strong>reate, <strong>R</strong>ead, <strong>U</strong>pdate, <strong>D</strong>elete: the four basic operations on data.</p><ul><li>Create: save a new user or inquiry</li><li>Read: search properties</li><li>Update: change a price or status</li><li>Delete: remove a record, if retention rules permit</li></ul>`),
      task(10, '10. Why does a database use indexes?', 'Answer it in your own words, then check.', '', `<p>With millions of rows, checking every row to find one is slow. An index gives the database a faster way to locate matching records, like the index at the back of a book.</p><div class="callout green"><div class="callout-title">Interview answer</div><p>An index lets the database find rows without scanning the whole table, which makes searches much faster.</p></div>`),
      task(11, 'What does SQL stand for?', 'Pick one answer, then check.', list(["Simple Query Logic","Structured Query Language","Standard Question List","Sequential Query Layer"]), `<p><strong>Answer: Structured Query Language</strong></p><p>SQL is Structured Query Language, the language used to talk to relational databases.</p>`),
      task(12, 'Which of these is a database management system, not a language?', 'Pick one answer, then check.', list(["SQL","PostgreSQL","CRUD","SEQUEL"]), `<p><strong>Answer: PostgreSQL</strong></p><p>PostgreSQL is a database system that understands SQL. SQL itself is the language.</p>`),
      task(13, 'Who proposed the relational model in 1970?', 'Pick one answer, then check.', list(["Edgar F. Codd","Donald Chamberlin","Raymond Boyce","Linus Torvalds"]), `<p><strong>Answer: Edgar F. Codd</strong></p><p>Codd proposed the relational model. Chamberlin and Boyce developed SEQUEL at IBM.</p>`),
      task(14, 'In the Orders table, why store customer_id instead of the customer name?', 'Pick one answer, then check.', list(["Numbers are always faster to print","So the name is stored once and referenced","Names are not allowed in tables","SQL cannot store text"]), `<p><strong>Answer: So the name is stored once and referenced</strong></p><p>Relationships let each order refer to a customer, avoiding repeated data.</p>`),
      task(15, 'Which problem do databases solve better than spreadsheets?', 'Pick one answer, then check.', list(["Many users editing at once safely","Drawing charts","Printing reports","Choosing fonts"]), `<p><strong>Answer: Many users editing at once safely</strong></p><p>Databases are built for concurrent access, constraints and transactions.</p>`),
      task(16, 'Which component picks an efficient way to run a query?', 'Pick one answer, then check.', list(["Parser","Query planner / optimizer","Storage engine","Frontend"]), `<p><strong>Answer: Query planner / optimizer</strong></p><p>The planner/optimizer chooses the plan; the parser only checks syntax.</p>`),
      task(17, 'What does the R in CRUD stand for?', 'Pick one answer, then check.', list(["Remove","Replace","Read","Relate"]), `<p><strong>Answer: Read</strong></p><p>CRUD = Create, Read, Update, Delete.</p>`),
      task(18, 'Why is an index useful?', 'Pick one answer, then check.', list(["It encrypts data","It lets the database find rows without scanning every row","It deletes duplicates","It backs up the database"]), `<p><strong>Answer: It lets the database find rows without scanning every row</strong></p><p>Indexes give the database a faster path to matching records.</p>`),
    ],
  });

  /* ---------- 3.2 Tables ---------- */
  subs.push({
    key: 'tables', title: 'Tables', lead: 'ER diagram of a mini Instagram: tables, primary keys, foreign keys and how they connect.',
    blocks: [
      block('Overview', '', `<div class="board erd-board"><svg class="illus erd" viewBox="0 0 1280 560" width="1280" style="max-width:100%;height:auto" role="img" aria-label="ER diagram of a mini Instagram: users, profiles, posts, comments, likes and follows" font-family="Inter, system-ui, -apple-system, Segoe UI, Arial, sans-serif"><polyline points="270,121 315,121 315,87 360,87" fill="none" stroke="#0d0d0d" stroke-width="1.8" stroke-linejoin="round"/><line x1="286" y1="130" x2="286" y2="112" stroke="#0d0d0d" stroke-width="1.8"/><line x1="344" y1="78" x2="344" y2="96" stroke="#0d0d0d" stroke-width="1.8"/><polyline points="680,121 635,121 635,87 590,87" fill="none" stroke="#0d0d0d" stroke-width="1.8" stroke-linejoin="round"/><line x1="662" y1="121" x2="680" y2="111" stroke="#0d0d0d" stroke-width="1.8"/><line x1="662" y1="121" x2="680" y2="131" stroke="#0d0d0d" stroke-width="1.8"/><line x1="606" y1="96" x2="606" y2="78" stroke="#0d0d0d" stroke-width="1.8"/><polyline points="910,155 955,155 955,87 1000,87" fill="none" stroke="#0d0d0d" stroke-width="1.8" stroke-linejoin="round"/><line x1="928" y1="155" x2="910" y2="165" stroke="#0d0d0d" stroke-width="1.8"/><line x1="928" y1="155" x2="910" y2="145" stroke="#0d0d0d" stroke-width="1.8"/><line x1="984" y1="78" x2="984" y2="96" stroke="#0d0d0d" stroke-width="1.8"/><polyline points="1115,206 1115,250 560,250 560,206" fill="none" stroke="#0d0d0d" stroke-width="1.8" stroke-linejoin="round"/><line x1="1115" y1="224" x2="1105" y2="206" stroke="#0d0d0d" stroke-width="1.8"/><line x1="1115" y1="224" x2="1125" y2="206" stroke="#0d0d0d" stroke-width="1.8"/><line x1="551" y1="222" x2="569" y2="222" stroke="#0d0d0d" stroke-width="1.8"/><polyline points="660,400 660,300 520,300 520,206" fill="none" stroke="#0d0d0d" stroke-width="1.8" stroke-linejoin="round"/><line x1="660" y1="382" x2="670" y2="400" stroke="#0d0d0d" stroke-width="1.8"/><line x1="660" y1="382" x2="650" y2="400" stroke="#0d0d0d" stroke-width="1.8"/><line x1="511" y1="222" x2="529" y2="222" stroke="#0d0d0d" stroke-width="1.8"/><polyline points="840,400 840,330 1160,330 1160,206" fill="none" stroke="#0d0d0d" stroke-width="1.8" stroke-linejoin="round"/><line x1="840" y1="382" x2="850" y2="400" stroke="#0d0d0d" stroke-width="1.8"/><line x1="840" y1="382" x2="830" y2="400" stroke="#0d0d0d" stroke-width="1.8"/><line x1="1151" y1="222" x2="1169" y2="222" stroke="#0d0d0d" stroke-width="1.8"/><polyline points="170,400 170,300 385,300 385,206" fill="none" stroke="#0d0d0d" stroke-width="1.8" stroke-linejoin="round"/><line x1="170" y1="382" x2="180" y2="400" stroke="#0d0d0d" stroke-width="1.8"/><line x1="170" y1="382" x2="160" y2="400" stroke="#0d0d0d" stroke-width="1.8"/><line x1="376" y1="222" x2="394" y2="222" stroke="#0d0d0d" stroke-width="1.8"/><polyline points="250,400 250,330 425,330 425,206" fill="none" stroke="#0d0d0d" stroke-width="1.8" stroke-linejoin="round"/><line x1="250" y1="382" x2="260" y2="400" stroke="#0d0d0d" stroke-width="1.8"/><line x1="250" y1="382" x2="240" y2="400" stroke="#0d0d0d" stroke-width="1.8"/><line x1="416" y1="222" x2="434" y2="222" stroke="#0d0d0d" stroke-width="1.8"/><rect x="40" y="30" width="230" height="176" rx="6" fill="#fff" stroke="#0d0d0d" stroke-width="1.8"/><path d="M40 70 V36 a6 6 0 0 1 6 -6 H264 a6 6 0 0 1 6 6 V70 Z" fill="#efefed" stroke="#0d0d0d" stroke-width="1.8"/><text x="155" y="56" text-anchor="middle" font-size="17" font-weight="700" fill="#0d0d0d">profiles</text><line x1="86" y1="70" x2="86" y2="206" stroke="#c9c9c4" stroke-width="1.4"/><text x="63" y="92" text-anchor="middle" font-size="13" font-weight="700" fill="#85500f">PK</text><text x="100" y="92.5" font-size="15" font-weight="600" fill="#0d0d0d">profile_id</text><line x1="40" y1="104" x2="270" y2="104" stroke="#ececea"/><text x="63" y="126" text-anchor="middle" font-size="13" font-weight="700" fill="#135238">FK</text><text x="100" y="126.5" font-size="15"  fill="#0d0d0d">user_id</text><line x1="40" y1="138" x2="270" y2="138" stroke="#ececea"/><text x="100" y="160.5" font-size="15"  fill="#0d0d0d">full_name</text><line x1="40" y1="172" x2="270" y2="172" stroke="#ececea"/><text x="100" y="194.5" font-size="15"  fill="#0d0d0d">bio</text><rect x="360" y="30" width="230" height="176" rx="6" fill="#fff" stroke="#0d0d0d" stroke-width="1.8"/><path d="M360 70 V36 a6 6 0 0 1 6 -6 H584 a6 6 0 0 1 6 6 V70 Z" fill="#efefed" stroke="#0d0d0d" stroke-width="1.8"/><text x="475" y="56" text-anchor="middle" font-size="17" font-weight="700" fill="#0d0d0d">users</text><line x1="406" y1="70" x2="406" y2="206" stroke="#c9c9c4" stroke-width="1.4"/><text x="383" y="92" text-anchor="middle" font-size="13" font-weight="700" fill="#85500f">PK</text><text x="420" y="92.5" font-size="15" font-weight="600" fill="#0d0d0d">user_id</text><line x1="360" y1="104" x2="590" y2="104" stroke="#ececea"/><text x="420" y="126.5" font-size="15"  fill="#0d0d0d">username</text><line x1="360" y1="138" x2="590" y2="138" stroke="#ececea"/><text x="420" y="160.5" font-size="15"  fill="#0d0d0d">email</text><line x1="360" y1="172" x2="590" y2="172" stroke="#ececea"/><text x="420" y="194.5" font-size="15"  fill="#0d0d0d">created_at</text><rect x="680" y="30" width="230" height="176" rx="6" fill="#fff" stroke="#0d0d0d" stroke-width="1.8"/><path d="M680 70 V36 a6 6 0 0 1 6 -6 H904 a6 6 0 0 1 6 6 V70 Z" fill="#efefed" stroke="#0d0d0d" stroke-width="1.8"/><text x="795" y="56" text-anchor="middle" font-size="17" font-weight="700" fill="#0d0d0d">comments</text><line x1="726" y1="70" x2="726" y2="206" stroke="#c9c9c4" stroke-width="1.4"/><text x="703" y="92" text-anchor="middle" font-size="13" font-weight="700" fill="#85500f">PK</text><text x="740" y="92.5" font-size="15" font-weight="600" fill="#0d0d0d">comment_id</text><line x1="680" y1="104" x2="910" y2="104" stroke="#ececea"/><text x="703" y="126" text-anchor="middle" font-size="13" font-weight="700" fill="#135238">FK</text><text x="740" y="126.5" font-size="15"  fill="#0d0d0d">user_id</text><line x1="680" y1="138" x2="910" y2="138" stroke="#ececea"/><text x="703" y="160" text-anchor="middle" font-size="13" font-weight="700" fill="#135238">FK</text><text x="740" y="160.5" font-size="15"  fill="#0d0d0d">post_id</text><line x1="680" y1="172" x2="910" y2="172" stroke="#ececea"/><text x="740" y="194.5" font-size="15"  fill="#0d0d0d">text</text><rect x="1000" y="30" width="230" height="176" rx="6" fill="#fff" stroke="#0d0d0d" stroke-width="1.8"/><path d="M1000 70 V36 a6 6 0 0 1 6 -6 H1224 a6 6 0 0 1 6 6 V70 Z" fill="#efefed" stroke="#0d0d0d" stroke-width="1.8"/><text x="1115" y="56" text-anchor="middle" font-size="17" font-weight="700" fill="#0d0d0d">posts</text><line x1="1046" y1="70" x2="1046" y2="206" stroke="#c9c9c4" stroke-width="1.4"/><text x="1023" y="92" text-anchor="middle" font-size="13" font-weight="700" fill="#85500f">PK</text><text x="1060" y="92.5" font-size="15" font-weight="600" fill="#0d0d0d">post_id</text><line x1="1000" y1="104" x2="1230" y2="104" stroke="#ececea"/><text x="1023" y="126" text-anchor="middle" font-size="13" font-weight="700" fill="#135238">FK</text><text x="1060" y="126.5" font-size="15"  fill="#0d0d0d">user_id</text><line x1="1000" y1="138" x2="1230" y2="138" stroke="#ececea"/><text x="1060" y="160.5" font-size="15"  fill="#0d0d0d">caption</text><line x1="1000" y1="172" x2="1230" y2="172" stroke="#ececea"/><text x="1060" y="194.5" font-size="15"  fill="#0d0d0d">created_at</text><rect x="120" y="400" width="230" height="142" rx="6" fill="#fff" stroke="#0d0d0d" stroke-width="1.8"/><path d="M120 440 V406 a6 6 0 0 1 6 -6 H344 a6 6 0 0 1 6 6 V440 Z" fill="#efefed" stroke="#0d0d0d" stroke-width="1.8"/><text x="235" y="426" text-anchor="middle" font-size="17" font-weight="700" fill="#0d0d0d">follows</text><line x1="166" y1="440" x2="166" y2="542" stroke="#c9c9c4" stroke-width="1.4"/><text x="143" y="462" text-anchor="middle" font-size="13" font-weight="700" fill="#85500f">PK</text><text x="180" y="462.5" font-size="15" font-weight="600" fill="#0d0d0d">follow_id</text><line x1="120" y1="474" x2="350" y2="474" stroke="#ececea"/><text x="143" y="496" text-anchor="middle" font-size="13" font-weight="700" fill="#135238">FK</text><text x="180" y="496.5" font-size="15"  fill="#0d0d0d">follower_id</text><line x1="120" y1="508" x2="350" y2="508" stroke="#ececea"/><text x="143" y="530" text-anchor="middle" font-size="13" font-weight="700" fill="#135238">FK</text><text x="180" y="530.5" font-size="15"  fill="#0d0d0d">following_id</text><rect x="640" y="400" width="230" height="142" rx="6" fill="#fff" stroke="#0d0d0d" stroke-width="1.8"/><path d="M640 440 V406 a6 6 0 0 1 6 -6 H864 a6 6 0 0 1 6 6 V440 Z" fill="#efefed" stroke="#0d0d0d" stroke-width="1.8"/><text x="755" y="426" text-anchor="middle" font-size="17" font-weight="700" fill="#0d0d0d">likes</text><line x1="686" y1="440" x2="686" y2="542" stroke="#c9c9c4" stroke-width="1.4"/><text x="663" y="462" text-anchor="middle" font-size="13" font-weight="700" fill="#85500f">PK</text><text x="700" y="462.5" font-size="15" font-weight="600" fill="#0d0d0d">like_id</text><line x1="640" y1="474" x2="870" y2="474" stroke="#ececea"/><text x="663" y="496" text-anchor="middle" font-size="13" font-weight="700" fill="#135238">FK</text><text x="700" y="496.5" font-size="15"  fill="#0d0d0d">user_id</text><line x1="640" y1="508" x2="870" y2="508" stroke="#ececea"/><text x="663" y="530" text-anchor="middle" font-size="13" font-weight="700" fill="#135238">FK</text><text x="700" y="530.5" font-size="15"  fill="#0d0d0d">post_id</text></svg></div><p class="erd-legend"><b>PK</b> primary key &nbsp;·&nbsp; <b>FK</b> foreign key &nbsp;·&nbsp; <svg width="30" height="14" viewBox="0 0 30 14" aria-hidden="true"><line x1="0" y1="7" x2="30" y2="7" stroke="#0d0d0d" stroke-width="1.8"/><line x1="15" y1="1" x2="15" y2="13" stroke="#0d0d0d" stroke-width="1.8"/></svg> one &nbsp;·&nbsp; <svg width="30" height="14" viewBox="0 0 30 14" aria-hidden="true"><line x1="0" y1="7" x2="30" y2="7" stroke="#0d0d0d" stroke-width="1.8"/><line x1="12" y1="7" x2="30" y2="1" stroke="#0d0d0d" stroke-width="1.8"/><line x1="12" y1="7" x2="30" y2="13" stroke="#0d0d0d" stroke-width="1.8"/></svg> many</p>`),
      block('Keys you must know', '', `<p>Keys are how tables identify their rows and point at each other. Every example below uses the diagram above. Scroll up and find the table as you read.</p><table class="tbl"><thead><tr><th>Key</th><th>One-line meaning</th><th>Example from the diagram</th></tr></thead><tbody><tr><td>Primary key</td><td>Uniquely identifies each row. No duplicates, no NULL.</td><td><code>users.user_id</code></td></tr><tr><td>Foreign key</td><td>Points at a row in another table.</td><td><code>posts.user_id</code> → <code>users.user_id</code></td></tr><tr><td>Super key</td><td>Any column set that identifies a row, extra columns allowed.</td><td><code>(user_id, username)</code></td></tr><tr><td>Candidate key</td><td>A minimal super key. Nothing can be removed.</td><td><code>user_id</code>, <code>email</code></td></tr><tr><td>Alternate key</td><td>A candidate key you did not pick as the primary key.</td><td><code>email</code></td></tr><tr><td>Composite key</td><td>A key made of two or more columns together.</td><td><code>(user_id, post_id)</code> in <code>likes</code></td></tr><tr><td>Unique key</td><td>A constraint that blocks duplicate values.</td><td><code>UNIQUE(email)</code></td></tr></tbody></table>`),
      block('Primary key (PK)', '', `<p>Uniquely identifies every row in a table. It cannot repeat and cannot be NULL.</p><div class="callout green"><div class="callout-title">In the diagram</div><p>Every table has a <strong>PK</strong> cell: <code>user_id</code> in <code>users</code>, <code>post_id</code> in <code>posts</code>, <code>like_id</code> in <code>likes</code>. Two users can never share a <code>user_id</code>.</p></div><div class="callout amber"><div class="callout-title">Interview question</div><p><strong>Can a table have two primary keys?</strong></p><p>No. A table has only one primary key <em>constraint</em>, but that one key can be made of several columns (a composite primary key).</p></div>`, '1'),
      block('Foreign key (FK)', '', `<p>Connects one table to another by referring to the primary key (or another unique key) of that table.</p><div class="callout green"><div class="callout-title">In the diagram</div><p>Every line in the diagram is a foreign key. <code>posts.user_id</code> holds a <code>users.user_id</code>, so each post knows who wrote it. The crow's foot sits on the FK side (many posts) and the bar on the PK side (one user).</p></div><div class="callout amber"><div class="callout-title">Interview question</div><p><strong>Can a foreign key contain duplicate values?</strong></p><p>Yes. One user can write many posts, so the same <code>user_id</code> appears on many rows of <code>posts</code>. A foreign key can also be NULL if the column allows it, which means "not linked to anything".</p></div>`, '2'),
      block('Candidate key', '', `<p>Any column, or combination of columns, that could identify a row and has nothing extra in it. Every candidate key is unique and not NULL.</p><div class="callout green"><div class="callout-title">In the diagram</div><p>In <code>users</code>, both <code>user_id</code> and <code>email</code> could identify a person, so both are candidate keys (assuming no two people share an email and none is empty).</p></div><div class="callout amber"><div class="callout-title">Interview question</div><p><strong>Candidate key vs primary key?</strong></p><p>Candidate keys are all the possible unique identifiers. The primary key is the one you choose from them.</p></div>`, '3'),
      block('Super key', '', `<p>Any set of columns that uniquely identifies a row, even if it carries unnecessary extra columns.</p><div class="callout green"><div class="callout-title">In the diagram</div><p><code>user_id</code> is a super key, and so is <code>(user_id, username)</code>, because <code>user_id</code> alone is already enough. The second one has a useless extra column.</p></div><p><strong>Difference:</strong> a candidate key is a <em>minimal</em> super key. You cannot remove a column from it without losing uniqueness.</p>`, '4'),
      block('Composite key', '', `<p>A key built from two or more columns together. Each column on its own may repeat, but the pair must not.</p><div class="callout green"><div class="callout-title">In the diagram</div><p><code>likes</code> uses <code>like_id</code> as its PK, but a common alternative is <code>(user_id, post_id)</code> as a composite key. Asha can like many posts and a post can have many likes, but Asha can like post 101 only once. <code>follows</code> works the same way with <code>(follower_id, following_id)</code>.</p></div>`, '5'),
      block('Alternate key', '', `<p>A candidate key that was not chosen as the primary key.</p><div class="callout green"><div class="callout-title">In the diagram</div><p><code>user_id</code> is the PK of <code>users</code>, so <code>email</code> (also a candidate key) is the alternate key.</p></div>`, '6'),
      block('Unique key', '', `<p>A constraint that prevents duplicate values in a column or a group of columns.</p><div class="callout green"><div class="callout-title">In the diagram</div><p><code>UNIQUE(email)</code> on <code>users</code> stops two accounts using the same email, even though <code>email</code> is not the primary key.</p></div><div class="callout amber"><div class="callout-title">Interview question</div><p><strong>Primary key vs unique key?</strong></p><p>A table has one primary key, and it cannot be NULL. A table can have many unique keys. How NULL is handled in a unique column depends on the database: PostgreSQL allows several NULLs, SQL Server allows only one.</p></div>`, '7'),
    ],
  });

  /* ---------- 3.3 Fundamentals ---------- */
  subs.push({
    key: 'fundamentals', title: 'Fundamentals', lead: 'Level 1 SQL in easy English: SELECT, WHERE, ORDER BY, LIMIT, DISTINCT, IN, BETWEEN, LIKE, INSERT, UPDATE, DELETE, NULL, aggregates, GROUP BY and HAVING.',
    blocks: [
      block('Overview', '', `<div class="callout green"><div class="callout-title">Level 1: write these without searching</div><p>SELECT, WHERE, ORDER BY, LIMIT · DISTINCT, IN, BETWEEN, LIKE · INSERT, UPDATE, DELETE · NULL, IS NULL, COALESCE · COUNT, SUM, AVG, MIN, MAX · GROUP BY and HAVING</p></div>`),
      block('Practice data', '', `<p>We use two tables from the Instagram diagram. For practice, <code>posts</code> also has a <code>views</code> column. Post 105 is brand new, so its views are <strong>NULL</strong> (unknown). Every example below starts from this data, so the examples do not affect each other.</p><div class="tv-grid"><div class="tv"><div class="tv-head">users<small>5 rows</small></div><div class="tv-scroll"><table><thead><tr><th>user_id</th><th>username</th><th>email</th><th>created_at</th></tr></thead><tbody><tr><td>1</td><td>shekar</td><td>shekar@mail.com</td><td>2026-01-05</td></tr><tr><td>2</td><td>asha</td><td>asha@mail.com</td><td>2026-01-12</td></tr><tr><td>3</td><td>ravi</td><td>ravi@mail.com</td><td>2026-02-03</td></tr><tr><td>4</td><td>meena</td><td>meena@mail.com</td><td>2026-02-20</td></tr><tr><td>5</td><td>kiran</td><td>kiran@mail.com</td><td>2026-03-08</td></tr></tbody></table></div></div><div class="tv"><div class="tv-head">posts<small>5 rows</small></div><div class="tv-scroll"><table><thead><tr><th>post_id</th><th>user_id</th><th>caption</th><th>views</th></tr></thead><tbody><tr><td>101</td><td>1</td><td>My first SQL table!</td><td>120</td></tr><tr><td>102</td><td>2</td><td>Sunset in Goa</td><td>340</td></tr><tr><td>103</td><td>1</td><td>Day 2: keys</td><td>80</td></tr><tr><td>104</td><td>3</td><td>Biryani time</td><td>210</td></tr><tr><td>105</td><td>2</td><td>Beach walk</td><td><span class="tv-null">NULL</span></td></tr></tbody></table></div></div></div>`),
      block('First, understand one query', '', `<div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT username, email
FROM users
WHERE user_id = 1;</code></pre></div><p>Read it like English: <em>"Give me the username and email, from the users table, where the user_id is 1."</em></p><div class="qbox"><div class="qrow"><span class="qk">SELECT</span><span class="qb">username, email</span><span class="qn">Which <strong>columns</strong> do I want?</span></div><div class="qrow"><span class="qk">FROM</span><span class="qb">users</span><span class="qn">Which <strong>table</strong>?</span></div><div class="qrow"><span class="qk opt">WHERE</span><span class="qb">user_id = 1</span><span class="qn">Which <strong>rows</strong>? <em>(optional)</em></span></div></div><div class="tv-grid"><div class="tv"><div class="tv-head">result<small>1 row</small></div><div class="tv-scroll"><table><thead><tr><th>username</th><th>email</th></tr></thead><tbody><tr><td>shekar</td><td>shekar@mail.com</td></tr></tbody></table></div></div></div><ul><li><strong>Statement</strong>: the whole instruction. It ends with a semicolon <code>;</code>.</li><li><strong>Clause</strong>: one part of a statement. It starts with a keyword and does one job. <code>SELECT …</code>, <code>FROM …</code> and <code>WHERE …</code> are three clauses.</li><li><strong>Keyword</strong>: a word SQL already knows (<code>SELECT</code>, <code>WHERE</code>). Capital letters are only a habit to make them easy to spot; SQL does not care.</li><li><strong>Condition</strong>: a test that is true or false for each row (<code>user_id = 1</code>).</li></ul><h4>The clauses, in the order you write them</h4><table class="tbl"><thead><tr><th>Clause</th><th>Job</th><th>Needed?</th></tr></thead><tbody><tr><td><code>SELECT</code></td><td>Pick columns (or calculations)</td><td>Yes</td></tr><tr><td><code>FROM</code></td><td>Pick the table</td><td>Yes (almost always)</td></tr><tr><td><code>WHERE</code></td><td>Keep only rows that pass a test</td><td>Optional</td></tr><tr><td><code>GROUP BY</code></td><td>Put rows into buckets</td><td>Optional</td></tr><tr><td><code>HAVING</code></td><td>Keep only buckets that pass a test</td><td>Optional</td></tr><tr><td><code>ORDER BY</code></td><td>Sort the result</td><td>Optional</td></tr><tr><td><code>LIMIT</code></td><td>Keep only the first N rows</td><td>Optional</td></tr></tbody></table><figure class="figure" data-fig="flow" data-args="{&quot;items&quot;:[{&quot;t&quot;:&quot;FROM&quot;,&quot;c&quot;:&quot;&quot;},{&quot;t&quot;:&quot;WHERE&quot;,&quot;c&quot;:&quot;&quot;},{&quot;t&quot;:&quot;GROUP BY&quot;,&quot;c&quot;:&quot;&quot;},{&quot;t&quot;:&quot;HAVING&quot;,&quot;c&quot;:&quot;&quot;},{&quot;t&quot;:&quot;SELECT&quot;,&quot;c&quot;:&quot;green&quot;},{&quot;t&quot;:&quot;ORDER BY&quot;,&quot;c&quot;:&quot;&quot;},{&quot;t&quot;:&quot;LIMIT&quot;,&quot;c&quot;:&quot;&quot;}],&quot;opts&quot;:{&quot;w&quot;:104,&quot;gap&quot;:26}}"><figcaption>The database reads the clauses in this order, which is different from the order you write them.</figcaption></figure><h4>What happens when you leave something out (defaults)</h4><table class="tbl"><thead><tr><th>If you do not write…</th><th>The database assumes</th></tr></thead><tbody><tr><td><code>WHERE</code></td><td>Every row. <code>SELECT * FROM users;</code> returns the whole table.</td></tr><tr><td><code>SELECT *</code> instead of column names</td><td>Every column.</td></tr><tr><td><code>ORDER BY</code></td><td>No guaranteed order. Never rely on it.</td></tr><tr><td>a direction after <code>ORDER BY</code></td><td><code>ASC</code> (smallest first). Write <code>DESC</code> for biggest first.</td></tr><tr><td><code>LIMIT</code></td><td>All the rows.</td></tr><tr><td><code>DISTINCT</code></td><td>Keep duplicates (<code>ALL</code>).</td></tr><tr><td>a column in <code>INSERT</code></td><td>Its <code>DEFAULT</code> value, or <code>NULL</code> if it has none.</td></tr><tr><td><code>WHERE</code> in <code>UPDATE</code> / <code>DELETE</code></td><td><strong>Every row.</strong> This is the classic mistake.</td></tr></tbody></table><p>Small rules: text goes in <strong>single quotes</strong> (<code>'asha'</code>), numbers do not, and <code>AND</code> is worked out before <code>OR</code>, so use brackets when you mix them.</p>`),
      block('SELECT, WHERE, ORDER BY, LIMIT', '', `<h4>SELECT: choose columns</h4><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT * FROM posts;                  -- every column
SELECT username, email FROM users;    -- only these two</code></pre></div><div class="tv-grid"><div class="tv"><div class="tv-head">result<small>5 rows</small></div><div class="tv-scroll"><table><thead><tr><th>username</th><th>email</th></tr></thead><tbody><tr><td>shekar</td><td>shekar@mail.com</td></tr><tr><td>asha</td><td>asha@mail.com</td></tr><tr><td>ravi</td><td>ravi@mail.com</td></tr><tr><td>meena</td><td>meena@mail.com</td></tr><tr><td>kiran</td><td>kiran@mail.com</td></tr></tbody></table></div></div></div><h4>WHERE: choose rows</h4><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT caption, views
FROM posts
WHERE views &gt; 100;</code></pre></div><div class="tv-grid"><div class="tv"><div class="tv-head">result<small>3 rows</small></div><div class="tv-scroll"><table><thead><tr><th>caption</th><th>views</th></tr></thead><tbody><tr><td>My first SQL table!</td><td>120</td></tr><tr><td>Sunset in Goa</td><td>340</td></tr><tr><td>Biryani time</td><td>210</td></tr></tbody></table></div></div></div><p class="tv-note">Post 105 is missing because NULL is not greater than 100. NULL is covered in section 4.</p><table class="tbl"><thead><tr><th>Operator</th><th>Meaning</th></tr></thead><tbody><tr><td><code>=</code> &nbsp; <code>&lt;&gt;</code> (or <code>!=</code>)</td><td>equal · not equal</td></tr><tr><td><code>&gt;</code> &nbsp; <code>&lt;</code> &nbsp; <code>&gt;=</code> &nbsp; <code>&lt;=</code></td><td>greater · smaller · or equal</td></tr><tr><td><code>AND</code> &nbsp; <code>OR</code> &nbsp; <code>NOT</code></td><td>combine tests: both · either · opposite</td></tr></tbody></table><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT caption FROM posts
WHERE views &gt; 100 AND user_id = 2;    -- both must be true</code></pre></div><div class="tv-grid"><div class="tv"><div class="tv-head">result<small>1 row</small></div><div class="tv-scroll"><table><thead><tr><th>caption</th></tr></thead><tbody><tr><td>Sunset in Goa</td></tr></tbody></table></div></div></div><h4>ORDER BY: sort</h4><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT caption, views
FROM posts
WHERE views &gt; 100
ORDER BY views DESC;</code></pre></div><div class="tv-grid"><div class="tv"><div class="tv-head">result<small>3 rows</small></div><div class="tv-scroll"><table><thead><tr><th>caption</th><th>views</th></tr></thead><tbody><tr><td>Sunset in Goa</td><td>340</td></tr><tr><td>Biryani time</td><td>210</td></tr><tr><td>My first SQL table!</td><td>120</td></tr></tbody></table></div></div></div><p class="tv-note"><code>ASC</code> is the default. Sort by several columns with a comma: <code>ORDER BY user_id ASC, views DESC</code>.</p><h4>LIMIT: keep the first N rows</h4><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT caption, views
FROM posts
WHERE views &gt; 100
ORDER BY views DESC
LIMIT 2;                              -- top 2 most viewed</code></pre></div><div class="tv-grid"><div class="tv"><div class="tv-head">result<small>2 rows</small></div><div class="tv-scroll"><table><thead><tr><th>caption</th><th>views</th></tr></thead><tbody><tr><td>Sunset in Goa</td><td>340</td></tr><tr><td>Biryani time</td><td>210</td></tr></tbody></table></div></div></div><div class="callout amber"><div class="callout-title">Remember</div><p>Use <code>LIMIT</code> with <code>ORDER BY</code>. Without a sort, "the first 2" is just any 2.</p></div>`, '1'),
      block('DISTINCT, IN, BETWEEN, LIKE', '', `<h4>DISTINCT: remove repeated values</h4><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT DISTINCT user_id FROM posts;</code></pre></div><div class="tv-grid"><div class="tv"><div class="tv-head">result<small>3 rows</small></div><div class="tv-scroll"><table><thead><tr><th>user_id</th></tr></thead><tbody><tr><td>1</td></tr><tr><td>2</td></tr><tr><td>3</td></tr></tbody></table></div></div></div><p class="tv-note"><code>posts</code> has 5 rows, but only 3 different people wrote them.</p><h4>IN: match any value from a list</h4><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT username FROM users
WHERE user_id IN (1, 3, 5);</code></pre></div><div class="tv-grid"><div class="tv"><div class="tv-head">result<small>3 rows</small></div><div class="tv-scroll"><table><thead><tr><th>username</th></tr></thead><tbody><tr><td>shekar</td></tr><tr><td>ravi</td></tr><tr><td>kiran</td></tr></tbody></table></div></div></div><p class="tv-note">Same as <code>user_id = 1 OR user_id = 3 OR user_id = 5</code>, just shorter. <code>NOT IN</code> is the opposite.</p><h4>BETWEEN: a range, both ends included</h4><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT caption, views FROM posts
WHERE views BETWEEN 100 AND 250;</code></pre></div><div class="tv-grid"><div class="tv"><div class="tv-head">result<small>2 rows</small></div><div class="tv-scroll"><table><thead><tr><th>caption</th><th>views</th></tr></thead><tbody><tr><td>My first SQL table!</td><td>120</td></tr><tr><td>Biryani time</td><td>210</td></tr></tbody></table></div></div></div><p class="tv-note">Same as <code>views &gt;= 100 AND views &lt;= 250</code>. Works for dates too.</p><h4>LIKE: match a pattern in text</h4><p><code>%</code> means any number of characters (even none). <code>_</code> means exactly one character.</p><table class="tbl"><thead><tr><th>Pattern</th><th>Meaning</th><th>Matches in posts.caption</th></tr></thead><tbody><tr><td><code>'S%'</code></td><td>starts with S</td><td>Sunset in Goa</td></tr><tr><td><code>'%time'</code></td><td>ends with "time"</td><td>Biryani time</td></tr><tr><td><code>'%SQL%'</code></td><td>contains "SQL"</td><td>My first SQL table!</td></tr><tr><td><code>'_ay%'</code></td><td>any one letter, then "ay"</td><td>Day 2: keys</td></tr></tbody></table><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT caption FROM posts
WHERE caption LIKE '%SQL%';</code></pre></div><div class="tv-grid"><div class="tv"><div class="tv-head">result<small>1 row</small></div><div class="tv-scroll"><table><thead><tr><th>caption</th></tr></thead><tbody><tr><td>My first SQL table!</td></tr></tbody></table></div></div></div><p class="tv-note">Upper and lower case: PostgreSQL <code>LIKE</code> cares about it (use <code>ILIKE</code> to ignore case). MySQL ignores case by default.</p>`, '2'),
      block('INSERT, UPDATE, DELETE', '', `<h4>INSERT: add a row</h4><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>INSERT INTO users (username, email)
VALUES ('divya', 'divya@mail.com');</code></pre></div><p>First list the columns, then give the values <strong>in the same order</strong>. We skipped <code>user_id</code> and <code>created_at</code>, so the database fills them from their defaults (an automatic id and today's date), as long as the table was created that way.</p><div class="tv-grid"><div class="tv"><div class="tv-head">users after INSERT<small>2 rows</small></div><div class="tv-scroll"><table><thead><tr><th>user_id</th><th>username</th><th>email</th><th>created_at</th></tr></thead><tbody><tr><td>5</td><td>kiran</td><td>kiran@mail.com</td><td>2026-03-08</td></tr><tr><td><strong>6</strong></td><td><strong>divya</strong></td><td><strong>divya@mail.com</strong></td><td><strong>2026-10-16</strong></td></tr></tbody></table></div></div></div><p class="tv-note">Several rows at once: <code>VALUES (…), (…), (…)</code>. Only the last existing row is shown above to save space.</p><h4>UPDATE: change rows</h4><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>UPDATE posts
SET views = 150
WHERE post_id = 105;</code></pre></div><div class="tv-grid"><div class="tv"><div class="tv-head">before<small>1 row</small></div><div class="tv-scroll"><table><thead><tr><th>post_id</th><th>caption</th><th>views</th></tr></thead><tbody><tr><td>105</td><td>Beach walk</td><td><span class="tv-null">NULL</span></td></tr></tbody></table></div></div><div class="tv"><div class="tv-head">after<small>1 row</small></div><div class="tv-scroll"><table><thead><tr><th>post_id</th><th>caption</th><th>views</th></tr></thead><tbody><tr><td>105</td><td>Beach walk</td><td><strong>150</strong></td></tr></tbody></table></div></div></div><p class="tv-note">Change more than one column with a comma: <code>SET views = 150, caption = 'Beach day'</code>.</p><h4>DELETE: remove rows</h4><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>DELETE FROM posts
WHERE post_id = 105;</code></pre></div><div class="callout amber"><div class="callout-title">Never forget WHERE</div><p><code>UPDATE</code> or <code>DELETE</code> without <code>WHERE</code> changes or removes <strong>every row</strong>. Safe habit: first run <code>SELECT * FROM posts WHERE post_id = 105;</code> and check you got exactly the rows you mean. Then change <code>SELECT *</code> to <code>DELETE</code>.</p></div>`, '3'),
      block('NULL, IS NULL, COALESCE', '', `<p><strong>NULL means "no value" or "unknown".</strong> It is not <code>0</code> and it is not empty text. Post 105 has no views recorded yet, so its <code>views</code> is NULL.</p><table class="tbl"><thead><tr><th>Rule</th><th>Example</th><th>Result</th></tr></thead><tbody><tr><td>Comparing with NULL is never true</td><td><code>views = NULL</code>, <code>views &gt; 100</code></td><td>row is left out</td></tr><tr><td>Maths with NULL gives NULL</td><td><code>views + 10</code></td><td>NULL</td></tr><tr><td>Aggregates skip NULL</td><td><code>AVG(views)</code></td><td>NULL values are ignored</td></tr></tbody></table><h4>IS NULL / IS NOT NULL</h4><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT post_id, caption FROM posts
WHERE views IS NULL;        -- not "= NULL"</code></pre></div><div class="tv-grid"><div class="tv"><div class="tv-head">result<small>1 row</small></div><div class="tv-scroll"><table><thead><tr><th>post_id</th><th>caption</th></tr></thead><tbody><tr><td>105</td><td>Beach walk</td></tr></tbody></table></div></div></div><p class="tv-note"><code>IS NOT NULL</code> gives the other four posts.</p><h4>COALESCE: replace NULL with a fallback</h4><p><code>COALESCE(a, b, …)</code> returns the <strong>first value that is not NULL</strong>. <code>AS</code> gives the result column a name.</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT caption, COALESCE(views, 0) AS views
FROM posts;</code></pre></div><div class="tv-grid"><div class="tv"><div class="tv-head">result<small>5 rows</small></div><div class="tv-scroll"><table><thead><tr><th>caption</th><th>views</th></tr></thead><tbody><tr><td>My first SQL table!</td><td>120</td></tr><tr><td>Sunset in Goa</td><td>340</td></tr><tr><td>Day 2: keys</td><td>80</td></tr><tr><td>Biryani time</td><td>210</td></tr><tr><td>Beach walk</td><td><strong>0</strong></td></tr></tbody></table></div></div></div><p class="tv-note">This changes only what you see. The table still stores NULL.</p>`, '4'),
      block('COUNT, SUM, AVG, MIN, MAX', '', `<p>An aggregate function looks at many rows and returns <strong>one value</strong>.</p><table class="tbl"><thead><tr><th>Function</th><th>Returns</th></tr></thead><tbody><tr><td><code>COUNT(*)</code></td><td>number of rows</td></tr><tr><td><code>COUNT(column)</code></td><td>number of rows where that column is not NULL</td></tr><tr><td><code>SUM(column)</code></td><td>total</td></tr><tr><td><code>AVG(column)</code></td><td>average</td></tr><tr><td><code>MIN(column)</code> &nbsp; <code>MAX(column)</code></td><td>smallest · biggest</td></tr></tbody></table><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT COUNT(*), COUNT(views), SUM(views),
       AVG(views), MIN(views), MAX(views)
FROM posts;</code></pre></div><div class="tv-grid"><div class="tv"><div class="tv-head">result<small>1 row</small></div><div class="tv-scroll"><table><thead><tr><th>COUNT(*)</th><th>COUNT(views)</th><th>SUM(views)</th><th>AVG(views)</th><th>MIN(views)</th><th>MAX(views)</th></tr></thead><tbody><tr><td>5</td><td>4</td><td>750</td><td>187.5</td><td>80</td><td>340</td></tr></tbody></table></div></div></div><p class="tv-note"><code>COUNT(*)</code> is 5 but <code>COUNT(views)</code> is 4, because post 105 is NULL. <code>AVG</code> is 750 ÷ 4 = 187.5, not 750 ÷ 5.</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT COUNT(*) FROM posts WHERE user_id = 1;   -- WHERE runs first, so this counts shekar's posts</code></pre></div><div class="tv-grid"><div class="tv"><div class="tv-head">result<small>1 row</small></div><div class="tv-scroll"><table><thead><tr><th>COUNT(*)</th></tr></thead><tbody><tr><td>2</td></tr></tbody></table></div></div></div>`, '5'),
      block('GROUP BY and HAVING', '', `<p>Without <code>GROUP BY</code>, an aggregate covers the whole table. <code>GROUP BY</code> first sorts rows into <strong>buckets</strong> (one per value), then runs the aggregate on each bucket.</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT user_id, COUNT(*) AS total_posts
FROM posts
GROUP BY user_id;</code></pre></div><div class="tv-grid"><div class="tv"><div class="tv-head">bucket user_id = 1<small>2 rows</small></div><div class="tv-scroll"><table><thead><tr><th>post_id</th><th>caption</th></tr></thead><tbody><tr><td>101</td><td>My first SQL table!</td></tr><tr><td>103</td><td>Day 2: keys</td></tr></tbody></table></div></div><div class="tv"><div class="tv-head">bucket user_id = 2<small>2 rows</small></div><div class="tv-scroll"><table><thead><tr><th>post_id</th><th>caption</th></tr></thead><tbody><tr><td>102</td><td>Sunset in Goa</td></tr><tr><td>105</td><td>Beach walk</td></tr></tbody></table></div></div><div class="tv"><div class="tv-head">bucket user_id = 3<small>1 row</small></div><div class="tv-scroll"><table><thead><tr><th>post_id</th><th>caption</th></tr></thead><tbody><tr><td>104</td><td>Biryani time</td></tr></tbody></table></div></div></div><div class="tv-grid"><div class="tv"><div class="tv-head">result<small>3 rows</small></div><div class="tv-scroll"><table><thead><tr><th>user_id</th><th>total_posts</th></tr></thead><tbody><tr><td>1</td><td>2</td></tr><tr><td>2</td><td>2</td></tr><tr><td>3</td><td>1</td></tr></tbody></table></div></div></div><div class="callout amber"><div class="callout-title">Rule</div><p>Every column in <code>SELECT</code> must either be in <code>GROUP BY</code> or be inside an aggregate like <code>COUNT()</code>. Otherwise the database does not know which value to show for the bucket.</p></div><h4>HAVING: filter the buckets</h4><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT user_id, COUNT(*) AS total_posts
FROM posts
GROUP BY user_id
HAVING COUNT(*) &gt;= 2;</code></pre></div><div class="tv-grid"><div class="tv"><div class="tv-head">result<small>2 rows</small></div><div class="tv-scroll"><table><thead><tr><th>user_id</th><th>total_posts</th></tr></thead><tbody><tr><td>1</td><td>2</td></tr><tr><td>2</td><td>2</td></tr></tbody></table></div></div></div><table class="tbl"><thead><tr><th></th><th>WHERE</th><th>HAVING</th></tr></thead><tbody><tr><td>Filters</td><td>individual <strong>rows</strong></td><td>whole <strong>groups</strong></td></tr><tr><td>Runs</td><td><strong>before</strong> GROUP BY</td><td><strong>after</strong> GROUP BY</td></tr><tr><td>Can use COUNT / SUM…?</td><td>No</td><td>Yes</td></tr></tbody></table><h4>All the clauses together</h4><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT user_id, SUM(views) AS total_views
FROM posts
WHERE views &gt; 100
GROUP BY user_id
HAVING SUM(views) &gt; 200
ORDER BY total_views DESC
LIMIT 5;</code></pre></div><p>In words: take posts with more than 100 views, group them by author, keep authors whose total is over 200, show the biggest total first, and stop at 5 rows.</p><div class="tv-grid"><div class="tv"><div class="tv-head">result<small>2 rows</small></div><div class="tv-scroll"><table><thead><tr><th>user_id</th><th>total_views</th></tr></thead><tbody><tr><td>2</td><td>340</td></tr><tr><td>3</td><td>210</td></tr></tbody></table></div></div></div>`, '6'),
      block('Write these from memory', '', `<ol>
      <li>Show the usernames of users created after 1 February 2026.</li>
      <li>Show the 3 most viewed posts.</li>
      <li>Show posts whose caption contains "keys".</li>
      <li>Show posts with no views recorded.</li>
      <li>Count how many posts each user wrote, but only for users with at least 2.</li>
      <li>Add a user named "neha" and then change her email to a new one.</li>
    </ol><details class="answers"><summary>Show answers</summary><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT username FROM users WHERE created_at &gt; '2026-02-01';

SELECT * FROM posts ORDER BY views DESC LIMIT 3;

SELECT * FROM posts WHERE caption LIKE '%keys%';

SELECT * FROM posts WHERE views IS NULL;

SELECT user_id, COUNT(*) FROM posts GROUP BY user_id HAVING COUNT(*) &gt;= 2;

INSERT INTO users (username, email) VALUES ('neha', 'neha@mail.com');
UPDATE users SET email = 'neha.new@mail.com' WHERE username = 'neha';</code></pre></div></details>`),
    ],
  });

  /* ---------- 3.4 Joins ---------- */
  subs.push({
    key: 'joins', title: 'Joins', lead: 'Level 2: INNER, LEFT and RIGHT joins, self joins, joining 3–4 tables, relationships, unmatched records and duplicate rows.',
    blocks: [
      block('Joins and relationships', 'Data lives in separate tables so nothing is repeated. A join puts the pieces back together when you need an answer that spans tables.', `<ul class="topics"><li>INNER, LEFT and RIGHT JOIN</li><li>Self joins</li><li>Joining 3–4 tables</li><li>One-to-one, one-to-many, many-to-many</li><li>Finding unmatched records</li><li>Avoiding duplicate rows after joins</li></ul><div class="jband"><div class="jband-t"><strong>Practice data</strong><span>Same Instagram tables as before. Note the gaps on purpose: meena and kiran have no posts, post 105 has no user, posts 104 and 105 have no likes.</span></div><div class="tv-grid"><div class="tv"><div class="tv-head">users<small>5 rows</small></div><div class="tv-scroll"><table><thead><tr><th>user_id</th><th>username</th><th>invited_by</th></tr></thead><tbody><tr><td>1</td><td>shekar</td><td><span class="tv-null">NULL</span></td></tr><tr><td>2</td><td>asha</td><td>1</td></tr><tr><td>3</td><td>ravi</td><td>1</td></tr><tr><td>4</td><td>meena</td><td>2</td></tr><tr><td>5</td><td>kiran</td><td><span class="tv-null">NULL</span></td></tr></tbody></table></div></div><div class="tv"><div class="tv-head">posts<small>5 rows</small></div><div class="tv-scroll"><table><thead><tr><th>post_id</th><th>user_id</th><th>caption</th></tr></thead><tbody><tr><td>101</td><td>1</td><td>My first SQL table!</td></tr><tr><td>102</td><td>2</td><td>Sunset in Goa</td></tr><tr><td>103</td><td>1</td><td>Day 2: keys</td></tr><tr><td>104</td><td>3</td><td>Biryani time</td></tr><tr><td>105</td><td><span class="tv-null">NULL</span></td><td>Anonymous post</td></tr></tbody></table></div></div><div class="tv"><div class="tv-head">likes<small>4 rows</small></div><div class="tv-scroll"><table><thead><tr><th>like_id</th><th>user_id</th><th>post_id</th></tr></thead><tbody><tr><td>1</td><td>2</td><td>101</td></tr><tr><td>2</td><td>3</td><td>101</td></tr><tr><td>3</td><td>1</td><td>102</td></tr><tr><td>4</td><td>2</td><td>103</td></tr></tbody></table></div></div><div class="tv"><div class="tv-head">profiles<small>3 rows</small></div><div class="tv-scroll"><table><thead><tr><th>profile_id</th><th>user_id</th><th>bio</th></tr></thead><tbody><tr><td>1</td><td>1</td><td>Learning SQL</td></tr><tr><td>2</td><td>2</td><td>Traveller</td></tr><tr><td>3</td><td>3</td><td>Foodie</td></tr></tbody></table></div></div></div></div>`),
      block('How a join works', 'Match a column in one table to a column in another, row by row.', `<div class="jgrid j2"><div class="jcard "><h4>The idea</h4><p>Each post stores only a <code>user_id</code>, not the username. To show <em>"Sunset in Goa by asha"</em>, the database looks up that <code>user_id</code> in <code>users</code>. That lookup is a join.</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT users.username, posts.caption
FROM users
INNER JOIN posts
  ON posts.user_id = users.user_id;</code></pre></div><div class="qbox">
          <div class="qrow"><span class="qk">FROM users</span><span class="qb"></span><span class="qn">the first table</span></div>
          <div class="qrow"><span class="qk">JOIN posts</span><span class="qb"></span><span class="qn">the table to attach</span></div>
          <div class="qrow"><span class="qk">ON …</span><span class="qb"></span><span class="qn">how rows match: <strong>foreign key = primary key</strong></span></div>
        </div><p>When two tables share a column name, write <code>table.column</code> so SQL knows which one you mean.</p><div class="callout amber"><div class="callout-title">Forgot the ON?</div><p>Without an <code>ON</code> condition every row pairs with every row (5 users × 5 posts = 25 rows). Always write it.</p></div></div><div class="jcard "><h4>What the database does</h4><p class="jsub">Green line = a match. Amber row = no match.</p><div class="jfig"><svg class="matchsvg" viewBox="0 0 580 208" role="img" aria-label="Rows of posts matched to rows of users" font-family="Inter, system-ui, Arial, sans-serif"><rect x="10" y="30" width="215" height="30" fill="#fff" stroke="#ececea"/><text x="24" y="50" font-size="13" fill="#0d0d0d"><tspan font-weight="600">post 101</tspan><tspan fill="#6b6b6b">   user_id = </tspan><tspan font-weight="600">1</tspan></text><rect x="10" y="60" width="215" height="30" fill="#fff" stroke="#ececea"/><text x="24" y="80" font-size="13" fill="#0d0d0d"><tspan font-weight="600">post 102</tspan><tspan fill="#6b6b6b">   user_id = </tspan><tspan font-weight="600">2</tspan></text><rect x="10" y="90" width="215" height="30" fill="#fff" stroke="#ececea"/><text x="24" y="110" font-size="13" fill="#0d0d0d"><tspan font-weight="600">post 103</tspan><tspan fill="#6b6b6b">   user_id = </tspan><tspan font-weight="600">1</tspan></text><rect x="10" y="120" width="215" height="30" fill="#fff" stroke="#ececea"/><text x="24" y="140" font-size="13" fill="#0d0d0d"><tspan font-weight="600">post 104</tspan><tspan fill="#6b6b6b">   user_id = </tspan><tspan font-weight="600">3</tspan></text><rect x="10" y="150" width="215" height="30" fill="#fbf0db" stroke="#ececea"/><text x="24" y="170" font-size="13" fill="#0d0d0d"><tspan font-weight="600">post 105</tspan><tspan fill="#6b6b6b">   user_id = </tspan><tspan font-style="italic" fill="#9b9b9b">NULL</tspan></text><rect x="365" y="30" width="200" height="30" fill="#fff" stroke="#ececea"/><text x="379" y="50" font-size="13" fill="#0d0d0d"><tspan fill="#6b6b6b">user_id = </tspan><tspan font-weight="600">1</tspan><tspan fill="#6b6b6b">   </tspan>shekar</text><rect x="365" y="60" width="200" height="30" fill="#fff" stroke="#ececea"/><text x="379" y="80" font-size="13" fill="#0d0d0d"><tspan fill="#6b6b6b">user_id = </tspan><tspan font-weight="600">2</tspan><tspan fill="#6b6b6b">   </tspan>asha</text><rect x="365" y="90" width="200" height="30" fill="#fff" stroke="#ececea"/><text x="379" y="110" font-size="13" fill="#0d0d0d"><tspan fill="#6b6b6b">user_id = </tspan><tspan font-weight="600">3</tspan><tspan fill="#6b6b6b">   </tspan>ravi</text><rect x="365" y="120" width="200" height="30" fill="#fbf0db" stroke="#ececea"/><text x="379" y="140" font-size="13" fill="#0d0d0d"><tspan fill="#6b6b6b">user_id = </tspan><tspan font-weight="600">4</tspan><tspan fill="#6b6b6b">   </tspan>meena</text><rect x="365" y="150" width="200" height="30" fill="#fbf0db" stroke="#ececea"/><text x="379" y="170" font-size="13" fill="#0d0d0d"><tspan fill="#6b6b6b">user_id = </tspan><tspan font-weight="600">5</tspan><tspan fill="#6b6b6b">   </tspan>kiran</text><path d="M225 45 C285 45 305 45 365 45" fill="none" stroke="#1e7a4c" stroke-width="2"/><circle cx="225" cy="45" r="4" fill="#1e7a4c"/><circle cx="365" cy="45" r="4" fill="#1e7a4c"/><path d="M225 75 C285 75 305 75 365 75" fill="none" stroke="#1e7a4c" stroke-width="2"/><circle cx="225" cy="75" r="4" fill="#1e7a4c"/><circle cx="365" cy="75" r="4" fill="#1e7a4c"/><path d="M225 105 C285 105 305 45 365 45" fill="none" stroke="#1e7a4c" stroke-width="2"/><circle cx="225" cy="105" r="4" fill="#1e7a4c"/><circle cx="365" cy="45" r="4" fill="#1e7a4c"/><path d="M225 135 C285 135 305 105 365 105" fill="none" stroke="#1e7a4c" stroke-width="2"/><circle cx="225" cy="135" r="4" fill="#1e7a4c"/><circle cx="365" cy="105" r="4" fill="#1e7a4c"/><rect x="10" y="0" width="215" height="30" rx="0" fill="#111"/><text x="22" y="19" font-size="13" font-weight="600" fill="#fff" font-family="ui-monospace, Consolas, monospace">posts</text><rect x="365" y="0" width="200" height="30" rx="0" fill="#111"/><text x="377" y="19" font-size="13" font-weight="600" fill="#fff" font-family="ui-monospace, Consolas, monospace">users</text><text x="295" y="200" text-anchor="middle" font-size="12" fill="#6b6b6b">posts.user_id = users.user_id</text></svg></div><p class="jsub">INNER JOIN keeps only the matched pairs. LEFT and RIGHT JOIN also keep the amber rows from one side, with NULL for the missing half.</p></div></div>`, '1'),
      block('INNER, LEFT and RIGHT JOIN', 'Same tables, same ON. The only difference is what happens to rows with no match.', `<div class="jgrid j3"><div class="jcard "><h4>INNER JOIN</h4><p class="jsub">Only rows that match on both sides.</p><svg class="venn" viewBox="0 0 190 100" role="img" aria-label="inner join" font-family="Inter, system-ui, Arial, sans-serif"><defs><clipPath id="vn1"><circle cx="70" cy="50" r="38"/></clipPath></defs><circle cx="120" cy="50" r="38" fill="#bfe0cf" clip-path="url(#vn1)"/><circle cx="70" cy="50" r="38" fill="none" stroke="#0d0d0d" stroke-width="1.6"/><circle cx="120" cy="50" r="38" fill="none" stroke="#0d0d0d" stroke-width="1.6"/><text x="52" y="54" text-anchor="middle" font-size="10" font-weight="600" fill="#0d0d0d">users</text><text x="138" y="54" text-anchor="middle" font-size="10" font-weight="600" fill="#0d0d0d">posts</text></svg><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT users.username, posts.caption
FROM users
INNER JOIN posts
  ON posts.user_id = users.user_id;</code></pre></div><div class="tv"><div class="tv-head">result<small>4 rows</small></div><div class="tv-scroll"><table><thead><tr><th>username</th><th>caption</th></tr></thead><tbody><tr><td>shekar</td><td>My first SQL table!</td></tr><tr><td>asha</td><td>Sunset in Goa</td></tr><tr><td>shekar</td><td>Day 2: keys</td></tr><tr><td>ravi</td><td>Biryani time</td></tr></tbody></table></div></div><p class="jnote">Lost: meena and kiran (no posts) and post 105 (no user). <code>JOIN</code> alone means INNER JOIN.</p></div><div class="jcard "><h4>LEFT JOIN</h4><p class="jsub">Every row from the left table, matched or not.</p><svg class="venn" viewBox="0 0 190 100" role="img" aria-label="left join" font-family="Inter, system-ui, Arial, sans-serif"><defs><clipPath id="vn2"><circle cx="70" cy="50" r="38"/></clipPath></defs><circle cx="70" cy="50" r="38" fill="#bfe0cf"/><circle cx="70" cy="50" r="38" fill="none" stroke="#0d0d0d" stroke-width="1.6"/><circle cx="120" cy="50" r="38" fill="none" stroke="#0d0d0d" stroke-width="1.6"/><text x="52" y="54" text-anchor="middle" font-size="10" font-weight="600" fill="#0d0d0d">users</text><text x="138" y="54" text-anchor="middle" font-size="10" font-weight="600" fill="#0d0d0d">posts</text></svg><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT users.username, posts.caption
FROM users
LEFT JOIN posts
  ON posts.user_id = users.user_id;</code></pre></div><div class="tv"><div class="tv-head">result<small>6 rows</small></div><div class="tv-scroll"><table><thead><tr><th>username</th><th>caption</th></tr></thead><tbody><tr><td>shekar</td><td>My first SQL table!</td></tr><tr><td>shekar</td><td>Day 2: keys</td></tr><tr><td>asha</td><td>Sunset in Goa</td></tr><tr><td>ravi</td><td>Biryani time</td></tr><tr class="hl"><td>meena</td><td><span class="tv-null">NULL</span></td></tr><tr class="hl"><td>kiran</td><td><span class="tv-null">NULL</span></td></tr></tbody></table></div></div><p class="jnote">Every user is kept. Where no post matches, the post columns are NULL. This is the most used outer join.</p></div><div class="jcard "><h4>RIGHT JOIN</h4><p class="jsub">Every row from the right table, matched or not.</p><svg class="venn" viewBox="0 0 190 100" role="img" aria-label="right join" font-family="Inter, system-ui, Arial, sans-serif"><defs><clipPath id="vn3"><circle cx="70" cy="50" r="38"/></clipPath></defs><circle cx="120" cy="50" r="38" fill="#bfe0cf"/><circle cx="70" cy="50" r="38" fill="none" stroke="#0d0d0d" stroke-width="1.6"/><circle cx="120" cy="50" r="38" fill="none" stroke="#0d0d0d" stroke-width="1.6"/><text x="52" y="54" text-anchor="middle" font-size="10" font-weight="600" fill="#0d0d0d">users</text><text x="138" y="54" text-anchor="middle" font-size="10" font-weight="600" fill="#0d0d0d">posts</text></svg><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT users.username, posts.caption
FROM users
RIGHT JOIN posts
  ON posts.user_id = users.user_id;</code></pre></div><div class="tv"><div class="tv-head">result<small>5 rows</small></div><div class="tv-scroll"><table><thead><tr><th>username</th><th>caption</th></tr></thead><tbody><tr><td>shekar</td><td>My first SQL table!</td></tr><tr><td>asha</td><td>Sunset in Goa</td></tr><tr><td>shekar</td><td>Day 2: keys</td></tr><tr><td>ravi</td><td>Biryani time</td></tr><tr class="hl"><td><span class="tv-null">NULL</span></td><td>Anonymous post</td></tr></tbody></table></div></div><p class="jnote">Every post is kept, even the one with no user. A RIGHT JOIN is a LEFT JOIN with the tables swapped, so many people only use LEFT.</p></div></div><div class="callout amber"><div class="callout-title">Remember</div><p>"Left" and "right" mean the table written <strong>before</strong> and <strong>after</strong> the word JOIN. Rows can come back in any order unless you add <code>ORDER BY</code>.</p></div>`, '2'),
      block('Self join', 'A table joined to itself, to compare one row with another row of the same table.', `<div class="jgrid j2"><div class="jcard "><h4>Who invited whom?</h4><p class="jsub"><code>users.invited_by</code> holds the <code>user_id</code> of the person who invited you. Both sides live in the same table.</p><div class="jfig"><svg class="relsvg" viewBox="0 0 400 80" role="img" aria-label="relationship diagram"><line x1="155" y1="40" x2="245" y2="40" stroke="#0d0d0d" stroke-width="1.7"/><line x1="171" y1="40" x2="155" y2="31" stroke="#0d0d0d" stroke-width="1.7"/><line x1="171" y1="40" x2="155" y2="49" stroke="#0d0d0d" stroke-width="1.7"/><line x1="231" y1="31" x2="231" y2="49" stroke="#0d0d0d" stroke-width="1.7"/><rect x="5" y="20" width="150" height="40" rx="8" fill="#fff" stroke="#0d0d0d" stroke-width="1.7"/><text x="80" y="45" text-anchor="middle" font-size="14" font-weight="700" font-family="ui-monospace, Consolas, monospace" fill="#0d0d0d">users AS u</text><rect x="245" y="20" width="150" height="40" rx="8" fill="#fff" stroke="#0d0d0d" stroke-width="1.7"/><text x="320" y="45" text-anchor="middle" font-size="14" font-weight="700" font-family="ui-monospace, Consolas, monospace" fill="#0d0d0d">users AS inv</text></svg></div><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT u.username AS username,
       inv.username AS invited_by
FROM users AS u
LEFT JOIN users AS inv
  ON u.invited_by = inv.user_id;</code></pre></div><p>Use the table <strong>twice with two different aliases</strong> (<code>u</code> and <code>inv</code>). Think of them as two copies: <code>u</code> is the person, <code>inv</code> is their inviter. Aliases are required here, otherwise SQL cannot tell the copies apart.</p></div><div class="jcard "><h4>Result</h4><p class="jsub">LEFT JOIN keeps people nobody invited.</p><div class="tv"><div class="tv-head">result<small>5 rows</small></div><div class="tv-scroll"><table><thead><tr><th>username</th><th>invited_by</th></tr></thead><tbody><tr><td>shekar</td><td><span class="tv-null">NULL</span></td></tr><tr><td>asha</td><td>shekar</td></tr><tr><td>ravi</td><td>shekar</td></tr><tr><td>meena</td><td>asha</td></tr><tr><td>kiran</td><td><span class="tv-null">NULL</span></td></tr></tbody></table></div></div><p class="jnote">shekar and kiran joined on their own, so <code>invited_by</code> is NULL and no inviter matches. With an INNER JOIN they would disappear.</p><p class="jnote">Other self-join uses: employee and manager, a category and its parent category, two rows of the same table that share a value.</p></div></div>`, '3'),
      block('Joining 3–4 tables', 'Add one JOIN per table. Each ON links the new table to one that is already in the query.', `<div class="jgrid j2"><div class="jcard "><h4>Who liked whose post?</h4><p class="jsub">Needs <code>likes</code>, <code>users</code> (the liker), <code>posts</code>, and <code>users</code> again (the author).</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT liker.username  AS liker,
       p.caption,
       author.username AS author
FROM likes AS l
JOIN users AS liker
  ON liker.user_id = l.user_id
JOIN posts AS p
  ON p.post_id = l.post_id
JOIN users AS author
  ON author.user_id = p.user_id;</code></pre></div><ol class="tv-steps">
          <li>Start with the table that holds the facts: <code>likes</code>.</li>
          <li>Add <code>users AS liker</code> through <code>l.user_id</code>.</li>
          <li>Add <code>posts</code> through <code>l.post_id</code>.</li>
          <li>Add <code>users AS author</code> through <code>p.user_id</code>. Same table, second alias.</li>
        </ol></div><div class="jcard "><h4>Result</h4><div class="tv"><div class="tv-head">result<small>4 rows</small></div><div class="tv-scroll"><table><thead><tr><th>liker</th><th>caption</th><th>author</th></tr></thead><tbody><tr><td>asha</td><td>My first SQL table!</td><td>shekar</td></tr><tr><td>ravi</td><td>My first SQL table!</td><td>shekar</td></tr><tr><td>shekar</td><td>Sunset in Goa</td><td>asha</td></tr><tr><td>asha</td><td>Day 2: keys</td><td>shekar</td></tr></tbody></table></div></div><p class="jnote">Each like row is looked up three times. Four likes, four result rows.</p><div class="callout green"><div class="callout-title">Tips for bigger joins</div><p>Build it one JOIN at a time and run it after each step. Give every table a short alias. Choose LEFT JOIN for any table whose rows might be missing, otherwise an INNER JOIN silently drops rows.</p></div></div></div>`, '4'),
      block('One-to-one, one-to-many, many-to-many', 'The relationship decides where the foreign key goes.', `<div class="jgrid j3"><div class="jcard "><h4>One-to-one</h4><p class="jsub">One user has one profile.</p><div class="jfig"><svg class="relsvg" viewBox="0 0 400 80" role="img" aria-label="relationship diagram"><line x1="130" y1="40" x2="270" y2="40" stroke="#0d0d0d" stroke-width="1.7"/><line x1="144" y1="31" x2="144" y2="49" stroke="#0d0d0d" stroke-width="1.7"/><line x1="256" y1="31" x2="256" y2="49" stroke="#0d0d0d" stroke-width="1.7"/><rect x="5" y="20" width="125" height="40" rx="8" fill="#fff" stroke="#0d0d0d" stroke-width="1.7"/><text x="67.5" y="45" text-anchor="middle" font-size="14" font-weight="700" font-family="ui-monospace, Consolas, monospace" fill="#0d0d0d">users</text><rect x="270" y="20" width="125" height="40" rx="8" fill="#fff" stroke="#0d0d0d" stroke-width="1.7"/><text x="332.5" y="45" text-anchor="middle" font-size="14" font-weight="700" font-family="ui-monospace, Consolas, monospace" fill="#0d0d0d">profiles</text></svg></div><p><code>profiles.user_id</code> is a foreign key and also <strong>UNIQUE</strong>, so a user can only have one profile.</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT u.username, pr.bio
FROM users u
LEFT JOIN profiles pr
  ON pr.user_id = u.user_id;</code></pre></div><p class="jnote">Result: one row per user. meena and kiran get a NULL bio.</p></div><div class="jcard "><h4>One-to-many</h4><p class="jsub">One user writes many posts.</p><div class="jfig"><svg class="relsvg" viewBox="0 0 400 80" role="img" aria-label="relationship diagram"><line x1="130" y1="40" x2="270" y2="40" stroke="#0d0d0d" stroke-width="1.7"/><line x1="144" y1="31" x2="144" y2="49" stroke="#0d0d0d" stroke-width="1.7"/><line x1="254" y1="40" x2="270" y2="31" stroke="#0d0d0d" stroke-width="1.7"/><line x1="254" y1="40" x2="270" y2="49" stroke="#0d0d0d" stroke-width="1.7"/><rect x="5" y="20" width="125" height="40" rx="8" fill="#fff" stroke="#0d0d0d" stroke-width="1.7"/><text x="67.5" y="45" text-anchor="middle" font-size="14" font-weight="700" font-family="ui-monospace, Consolas, monospace" fill="#0d0d0d">users</text><rect x="270" y="20" width="125" height="40" rx="8" fill="#fff" stroke="#0d0d0d" stroke-width="1.7"/><text x="332.5" y="45" text-anchor="middle" font-size="14" font-weight="700" font-family="ui-monospace, Consolas, monospace" fill="#0d0d0d">posts</text></svg></div><p>The foreign key goes on the <strong>many</strong> side: <code>posts.user_id</code>. The most common relationship.</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT u.username, p.caption
FROM users u
JOIN posts p
  ON p.user_id = u.user_id;</code></pre></div><p class="jnote">Result: shekar appears twice, once per post. The "one" side repeats.</p></div><div class="jcard "><h4>Many-to-many</h4><p class="jsub">A user likes many posts, a post is liked by many users.</p><div class="jfig"><svg class="relsvg" viewBox="0 0 400 80" role="img" aria-label="relationship diagram"><line x1="100" y1="40" x2="150" y2="40" stroke="#0d0d0d" stroke-width="1.7"/><line x1="114" y1="31" x2="114" y2="49" stroke="#0d0d0d" stroke-width="1.7"/><line x1="134" y1="40" x2="150" y2="31" stroke="#0d0d0d" stroke-width="1.7"/><line x1="134" y1="40" x2="150" y2="49" stroke="#0d0d0d" stroke-width="1.7"/><line x1="250" y1="40" x2="300" y2="40" stroke="#0d0d0d" stroke-width="1.7"/><line x1="266" y1="40" x2="250" y2="31" stroke="#0d0d0d" stroke-width="1.7"/><line x1="266" y1="40" x2="250" y2="49" stroke="#0d0d0d" stroke-width="1.7"/><line x1="286" y1="31" x2="286" y2="49" stroke="#0d0d0d" stroke-width="1.7"/><rect x="5" y="20" width="95" height="40" rx="8" fill="#fff" stroke="#0d0d0d" stroke-width="1.7"/><text x="52.5" y="45" text-anchor="middle" font-size="14" font-weight="700" font-family="ui-monospace, Consolas, monospace" fill="#0d0d0d">users</text><rect x="150" y="20" width="100" height="40" rx="8" fill="#fff" stroke="#0d0d0d" stroke-width="1.7"/><text x="200" y="45" text-anchor="middle" font-size="14" font-weight="700" font-family="ui-monospace, Consolas, monospace" fill="#0d0d0d">likes</text><rect x="300" y="20" width="95" height="40" rx="8" fill="#fff" stroke="#0d0d0d" stroke-width="1.7"/><text x="347.5" y="45" text-anchor="middle" font-size="14" font-weight="700" font-family="ui-monospace, Consolas, monospace" fill="#0d0d0d">posts</text></svg></div><p>Two tables cannot hold this directly, so add a <strong>junction table</strong> (<code>likes</code>) with two foreign keys.</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT u.username, p.caption
FROM likes l
JOIN users u ON u.user_id = l.user_id
JOIN posts p ON p.post_id = l.post_id;</code></pre></div><p class="jnote">You always join <em>through</em> the junction table.</p></div></div>`, '5'),
      block('Finding unmatched records', 'LEFT JOIN, then keep only the rows where the right side is NULL.', `<div class="jgrid j2"><div class="jcard "><h4>Users who have never posted</h4><svg class="venn" viewBox="0 0 190 100" role="img" aria-label="anti join" font-family="Inter, system-ui, Arial, sans-serif"><defs><clipPath id="vn4"><circle cx="70" cy="50" r="38"/></clipPath></defs><circle cx="70" cy="50" r="38" fill="#bfe0cf"/><circle cx="120" cy="50" r="38" fill="#fff" clip-path="url(#vn4)"/><circle cx="70" cy="50" r="38" fill="none" stroke="#0d0d0d" stroke-width="1.6"/><circle cx="120" cy="50" r="38" fill="none" stroke="#0d0d0d" stroke-width="1.6"/><text x="52" y="54" text-anchor="middle" font-size="10" font-weight="600" fill="#0d0d0d">users</text><text x="138" y="54" text-anchor="middle" font-size="10" font-weight="600" fill="#0d0d0d">posts</text></svg><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT users.username
FROM users
LEFT JOIN posts
  ON posts.user_id = users.user_id
WHERE posts.post_id IS NULL;</code></pre></div><div class="tv"><div class="tv-head">result<small>2 rows</small></div><div class="tv-scroll"><table><thead><tr><th>username</th></tr></thead><tbody><tr><td>meena</td></tr><tr><td>kiran</td></tr></tbody></table></div></div></div><div class="jcard "><h4>Posts nobody has liked</h4><svg class="venn" viewBox="0 0 190 100" role="img" aria-label="anti join" font-family="Inter, system-ui, Arial, sans-serif"><defs><clipPath id="vn5"><circle cx="70" cy="50" r="38"/></clipPath></defs><circle cx="70" cy="50" r="38" fill="#bfe0cf"/><circle cx="120" cy="50" r="38" fill="#fff" clip-path="url(#vn5)"/><circle cx="70" cy="50" r="38" fill="none" stroke="#0d0d0d" stroke-width="1.6"/><circle cx="120" cy="50" r="38" fill="none" stroke="#0d0d0d" stroke-width="1.6"/><text x="52" y="54" text-anchor="middle" font-size="10" font-weight="600" fill="#0d0d0d">posts</text><text x="138" y="54" text-anchor="middle" font-size="10" font-weight="600" fill="#0d0d0d">likes</text></svg><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT p.post_id, p.caption
FROM posts p
LEFT JOIN likes l
  ON l.post_id = p.post_id
WHERE l.like_id IS NULL;</code></pre></div><div class="tv"><div class="tv-head">result<small>2 rows</small></div><div class="tv-scroll"><table><thead><tr><th>post_id</th><th>caption</th></tr></thead><tbody><tr><td>104</td><td>Biryani time</td></tr><tr><td>105</td><td>Anonymous post</td></tr></tbody></table></div></div></div></div><div class="jgrid j2"><div class="jcard "><h4>Why it works</h4><p>After a LEFT JOIN, a left row with no match gets NULL in every right-side column. Filtering <code>WHERE right.key IS NULL</code> keeps exactly those rows. This pattern is called an <strong>anti-join</strong>.</p><div class="callout amber"><div class="callout-title">Test the key, not any column</div><p>Check the right table's <strong>primary key</strong>. It can never be NULL in a real row, so NULL can only mean "no match". A nullable column could be NULL for a matched row too.</p></div></div><div class="jcard "><h4>Other ways to write it</h4><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT username FROM users u
WHERE NOT EXISTS (
  SELECT 1 FROM posts p
  WHERE p.user_id = u.user_id
);</code></pre></div><p><code>NOT EXISTS</code> gives the same answer. Avoid <code>NOT IN (subquery)</code>: if the subquery returns even one NULL (like post 105's <code>user_id</code>), it returns <strong>no rows at all</strong>.</p></div></div>`, '6'),
      block('Avoiding duplicate rows after joins', 'A one-to-many join repeats the "one" side once for every matching "many" row.', `<div class="jgrid j2"><div class="jcard "><h4>Why it happens</h4><p class="jsub">shekar has 2 posts, so he appears twice.</p><div class="tv"><div class="tv-head">result<small>4 rows</small></div><div class="tv-scroll"><table><thead><tr><th>username</th><th>caption</th></tr></thead><tbody><tr class="hl"><td>shekar</td><td>My first SQL table!</td></tr><tr><td>asha</td><td>Sunset in Goa</td></tr><tr class="hl"><td>shekar</td><td>Day 2: keys</td></tr><tr><td>ravi</td><td>Biryani time</td></tr></tbody></table></div></div><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>-- "How many users have posted?"
SELECT COUNT(*)
FROM users
JOIN posts ON posts.user_id = users.user_id;</code></pre></div><div class="tv"><div class="tv-head">result<small>1 row</small></div><div class="tv-scroll"><table><thead><tr><th>COUNT(*)</th></tr></thead><tbody><tr><td>4</td></tr></tbody></table></div></div><p class="jnote">Wrong. 4 is the number of <em>joined rows</em>. Only 3 users have posted.</p></div><div class="jcard "><h4>Also watch for</h4><ul class="jbul">
          <li><strong>Joining on a column that is not unique.</strong> If both sides repeat the value (for example joining two tables on <code>city</code>), every pair is produced.</li>
          <li><strong>Forgetting the ON.</strong> Gives every row × every row.</li>
          <li><strong>Joining several one-to-many tables at once.</strong> Posts and likes of one user multiply against each other, so counts and sums come out too big.</li>
        </ul><div class="callout green"><div class="callout-title">Habit</div><p>After writing a join, ask: <em>is each join key unique on at least one side?</em> and <em>how many rows should the answer have?</em> If the numbers do not match, rows are being duplicated.</p></div></div></div><div class="jgrid j3"><div class="jcard "><h4>Fix 1: DISTINCT</h4><p class="jsub">Remove repeated rows from the result.</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT DISTINCT users.username
FROM users
JOIN posts
  ON posts.user_id = users.user_id;</code></pre></div><div class="tv"><div class="tv-head">result<small>3 rows</small></div><div class="tv-scroll"><table><thead><tr><th>username</th></tr></thead><tbody><tr><td>shekar</td></tr><tr><td>asha</td></tr><tr><td>ravi</td></tr></tbody></table></div></div><p class="jnote">To count: <code>COUNT(DISTINCT users.user_id)</code> gives 3.</p></div><div class="jcard "><h4>Fix 2: GROUP BY</h4><p class="jsub">One row per user, with the many side counted.</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT users.username,
       COUNT(posts.post_id) AS posts
FROM users
LEFT JOIN posts
  ON posts.user_id = users.user_id
GROUP BY users.user_id, users.username;</code></pre></div><div class="tv"><div class="tv-head">result<small>5 rows</small></div><div class="tv-scroll"><table><thead><tr><th>username</th><th>posts</th></tr></thead><tbody><tr><td>shekar</td><td>2</td></tr><tr><td>asha</td><td>1</td></tr><tr><td>ravi</td><td>1</td></tr><tr><td>meena</td><td>0</td></tr><tr><td>kiran</td><td>0</td></tr></tbody></table></div></div><p class="jnote">Count a column of the right table (<code>posts.post_id</code>), not <code>*</code>. <code>COUNT(*)</code> would show 1 for meena.</p></div><div class="jcard "><h4>Fix 3: EXISTS</h4><p class="jsub">Do not join at all if you only need to know "has any".</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT username
FROM users u
WHERE EXISTS (
  SELECT 1 FROM posts p
  WHERE p.user_id = u.user_id
);</code></pre></div><div class="tv"><div class="tv-head">result<small>3 rows</small></div><div class="tv-scroll"><table><thead><tr><th>username</th></tr></thead><tbody><tr><td>shekar</td></tr><tr><td>asha</td></tr><tr><td>ravi</td></tr></tbody></table></div></div><p class="jnote">Each user is checked once, so duplicates cannot appear.</p></div></div>`, '7'),
      block('Cheat sheet', 'Pick the join from the question.', `<div class="jcard"><table class="tbl"><thead><tr><th>I want…</th><th>Use</th></tr></thead><tbody><tr><td>Only rows that match on both sides</td><td><code>INNER JOIN</code> (or just <code>JOIN</code>)</td></tr><tr><td>All rows from the first table, plus matches</td><td><code>LEFT JOIN</code></td></tr><tr><td>All rows from the second table, plus matches</td><td><code>RIGHT JOIN</code> (or swap the tables and use <code>LEFT JOIN</code>)</td></tr><tr><td>Rows in A that have nothing in B</td><td><code>A LEFT JOIN B … WHERE B.key IS NULL</code></td></tr><tr><td>To compare rows of the same table</td><td>Self join with two aliases</td></tr><tr><td>Three or more tables</td><td>One <code>JOIN … ON …</code> per extra table</td></tr><tr><td>Many-to-many data</td><td>Join through the junction table</td></tr><tr><td>One row per "one" side after a join</td><td><code>DISTINCT</code>, <code>GROUP BY</code> or <code>EXISTS</code></td></tr></tbody></table></div>`, '8'),
    ],
  });

  /* ---------- 3.5 Advanced SQL ---------- */
  subs.push({
    key: 'advanced', title: 'Advanced SQL', lead: 'Level 3: subqueries, CTEs, CASE WHEN, window functions, LAG and LEAD, set operations, second-highest salary and top N per group.',
    blocks: [
      block('Intermediate and advanced SQL', 'These topics separate someone who knows basic SQL from someone ready for backend interviews. Each one is a small idea. Take them one at a time.', `<ul class="topics"><li>Subqueries and correlated subqueries</li><li>CTEs using WITH</li><li>CASE WHEN</li><li>ROW_NUMBER, RANK, DENSE_RANK</li><li>PARTITION BY, OVER, LAG, LEAD</li><li>UNION, UNION ALL, INTERSECT</li><li>Second-highest salary</li><li>Top N records per group</li></ul><div class="jband"><div class="jband-t"><strong>Practice data</strong><span>An <code>employees</code> table. Ties are on purpose: Ravi and Meena both earn 80000, Divya and Neha both earn 70000.</span></div><div class="tv-grid"><div class="tv"><div class="tv-head">employees<small>8 rows</small></div><div class="tv-scroll"><table><thead><tr><th>emp_id</th><th>name</th><th>dept</th><th>salary</th></tr></thead><tbody><tr><td>1</td><td>Asha</td><td>Eng</td><td>90000</td></tr><tr><td>2</td><td>Ravi</td><td>Eng</td><td>80000</td></tr><tr><td>3</td><td>Meena</td><td>Eng</td><td>80000</td></tr><tr><td>4</td><td>Kiran</td><td>Sales</td><td>60000</td></tr><tr><td>5</td><td>Divya</td><td>Sales</td><td>70000</td></tr><tr><td>6</td><td>Neha</td><td>Sales</td><td>70000</td></tr><tr><td>7</td><td>Arjun</td><td>HR</td><td>50000</td></tr><tr><td>8</td><td>Sana</td><td>HR</td><td>65000</td></tr></tbody></table></div></div></div></div>`),
      block('Subqueries and correlated subqueries', 'A query inside another query. The inner one gives the outer one something to work with.', `<div class="jgrid j2"><div class="jcard "><h4>Plain subquery</h4><p class="jsub">The inner query runs <strong>once</strong>, first.</p><p>Question: <em>who earns more than the company average?</em> You cannot write <code>salary &gt; AVG(salary)</code> directly, so ask the average in a small query and use its answer.</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT name, salary
FROM employees
WHERE salary &gt; (
  SELECT AVG(salary) FROM employees
);</code></pre></div><div class="tv"><div class="tv-head">inner query returns<small>1 row</small></div><div class="tv-scroll"><table><thead><tr><th>AVG(salary)</th></tr></thead><tbody><tr><td>70625</td></tr></tbody></table></div></div><div class="tv"><div class="tv-head">result<small>3 rows</small></div><div class="tv-scroll"><table><thead><tr><th>name</th><th>salary</th></tr></thead><tbody><tr><td>Asha</td><td>90000</td></tr><tr><td>Ravi</td><td>80000</td></tr><tr><td>Meena</td><td>80000</td></tr></tbody></table></div></div><p class="jnote">The brackets matter. The inner query is replaced by its answer (70625), then the outer query runs as <code>salary &gt; 70625</code>.</p></div><div class="jcard "><h4>Correlated subquery</h4><p class="jsub">The inner query uses a column from the <strong>outer row</strong>, so it runs once per row.</p><p>Question: <em>who earns more than the average of <u>their own</u> department?</em> The average changes with every employee.</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT name, dept, salary
FROM employees e
WHERE salary &gt; (
  SELECT AVG(salary)
  FROM employees
  WHERE dept = e.dept   -- uses the outer row
);</code></pre></div><div class="tv"><div class="tv-head">what the database works out, row by row<small>8 rows</small></div><div class="tv-scroll"><table><thead><tr><th>name</th><th>dept</th><th>salary</th><th>own dept avg</th></tr></thead><tbody><tr class="ok"><td>Asha</td><td>Eng</td><td>90000</td><td>83333</td></tr><tr><td>Ravi</td><td>Eng</td><td>80000</td><td>83333</td></tr><tr><td>Meena</td><td>Eng</td><td>80000</td><td>83333</td></tr><tr><td>Kiran</td><td>Sales</td><td>60000</td><td>66667</td></tr><tr class="ok"><td>Divya</td><td>Sales</td><td>70000</td><td>66667</td></tr><tr class="ok"><td>Neha</td><td>Sales</td><td>70000</td><td>66667</td></tr><tr><td>Arjun</td><td>HR</td><td>50000</td><td>57500</td></tr><tr class="ok"><td>Sana</td><td>HR</td><td>65000</td><td>57500</td></tr></tbody></table></div></div><p class="jnote">Green rows are the answer: Asha, Divya, Neha, Sana. Correlated subqueries can be slow on big tables, so often a JOIN or a window function does the same job faster.</p></div></div><div class="jgrid j2"><div class="jcard "><h4>Where a subquery can sit</h4><table class="tbl"><thead><tr><th>Place</th><th>Gives back</th><th>Example</th></tr></thead><tbody><tr><td><code>WHERE</code> with <code>=</code> <code>&gt;</code></td><td>one value</td><td><code>salary &gt; (SELECT AVG…)</code></td></tr><tr><td><code>WHERE … IN</code></td><td>a list of values</td><td><code>dept IN (SELECT dept FROM …)</code></td></tr><tr><td><code>WHERE EXISTS</code></td><td>yes / no</td><td><code>EXISTS (SELECT 1 FROM …)</code></td></tr><tr><td><code>FROM</code></td><td>a temporary table (needs an alias)</td><td><code>FROM (SELECT …) AS t</code></td></tr><tr><td><code>SELECT</code></td><td>one value per row</td><td><code>(SELECT COUNT(*) …) AS total</code></td></tr></tbody></table></div><div class="jcard "><h4>Easy way to remember</h4><div class="callout green"><div class="callout-title">Plain vs correlated</div><p><strong>Plain:</strong> the inner query could run alone and always gives the same answer. <strong>Correlated:</strong> the inner query mentions the outer table (<code>e.dept</code>), so it cannot run alone.</p></div></div></div>`, '1'),
      block('CTEs using WITH', 'Give a query a name, then use that name like a table. It lives only for this one statement.', `<div class="jgrid j2"><div class="jcard "><h4>Same question, written in steps</h4><p class="jsub">Employees above their department average.</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>WITH dept_avg AS (
  SELECT dept, ROUND(AVG(salary), 2) AS avg_salary
  FROM employees
  GROUP BY dept
)
SELECT e.name, e.dept, e.salary, d.avg_salary
FROM employees e
JOIN dept_avg d ON d.dept = e.dept
WHERE e.salary &gt; d.avg_salary;</code></pre></div><p class="jnote">Read it top to bottom: <strong>Step 1</strong> build <code>dept_avg</code>. <strong>Step 2</strong> join to it.</p></div><div class="jcard "><h4>What each step produces</h4><div class="tv"><div class="tv-head">dept_avg (the CTE)<small>3 rows</small></div><div class="tv-scroll"><table><thead><tr><th>dept</th><th>avg_salary</th></tr></thead><tbody><tr><td>Eng</td><td>83333.33</td></tr><tr><td>Sales</td><td>66666.67</td></tr><tr><td>HR</td><td>57500.00</td></tr></tbody></table></div></div><div class="tv"><div class="tv-head">result<small>4 rows</small></div><div class="tv-scroll"><table><thead><tr><th>name</th><th>dept</th><th>salary</th><th>avg_salary</th></tr></thead><tbody><tr><td>Asha</td><td>Eng</td><td>90000</td><td>83333.33</td></tr><tr><td>Divya</td><td>Sales</td><td>70000</td><td>66666.67</td></tr><tr><td>Neha</td><td>Sales</td><td>70000</td><td>66666.67</td></tr><tr><td>Sana</td><td>HR</td><td>65000</td><td>57500.00</td></tr></tbody></table></div></div></div></div><div class="jgrid j2"><div class="jcard "><h4>Why use a CTE</h4><ul class="jbul"><li><strong>Readable.</strong> Long queries become small named steps.</li><li><strong>Reusable.</strong> Use the same name twice in one query.</li><li><strong>Chainable.</strong> <code>WITH a AS (…), b AS (…) SELECT …</code>, where <code>b</code> can use <code>a</code>.</li></ul></div><div class="jcard "><h4>Good to know</h4><ul class="jbul"><li>A CTE exists only for the one statement that follows it.</li><li>It is mostly about clarity. A CTE and an equivalent subquery usually run the same.</li><li><code>WITH RECURSIVE</code> lets a CTE call itself, used for trees such as categories and sub-categories.</li></ul></div></div>`, '2'),
      block('CASE WHEN', 'If-else inside SQL. It turns values into labels or conditional numbers.', `<div class="jgrid j2"><div class="jcard "><h4>Label each row</h4><p class="jsub">The first matching <code>WHEN</code> wins. No match and no <code>ELSE</code> gives NULL.</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT name, salary,
  CASE
    WHEN salary &gt;= 80000 THEN 'High'
    WHEN salary &gt;= 65000 THEN 'Medium'
    ELSE 'Low'
  END AS band
FROM employees;</code></pre></div><div class="tv"><div class="tv-head">result<small>8 rows</small></div><div class="tv-scroll"><table><thead><tr><th>name</th><th>salary</th><th>band</th></tr></thead><tbody><tr><td>Asha</td><td>90000</td><td>High</td></tr><tr><td>Ravi</td><td>80000</td><td>High</td></tr><tr><td>Meena</td><td>80000</td><td>High</td></tr><tr><td>Kiran</td><td>60000</td><td>Low</td></tr><tr><td>Divya</td><td>70000</td><td>Medium</td></tr><tr><td>Neha</td><td>70000</td><td>Medium</td></tr><tr><td>Arjun</td><td>50000</td><td>Low</td></tr><tr><td>Sana</td><td>65000</td><td>Medium</td></tr></tbody></table></div></div></div><div class="jcard "><h4>CASE inside an aggregate</h4><p class="jsub">Count only the rows that pass a test, per group.</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT dept,
  SUM(CASE WHEN salary &gt;= 70000
           THEN 1 ELSE 0 END) AS high_earners
FROM employees
GROUP BY dept;</code></pre></div><div class="tv"><div class="tv-head">result<small>3 rows</small></div><div class="tv-scroll"><table><thead><tr><th>dept</th><th>high_earners</th></tr></thead><tbody><tr><td>Eng</td><td>3</td></tr><tr><td>Sales</td><td>2</td></tr><tr><td>HR</td><td>0</td></tr></tbody></table></div></div><p class="jnote">Each row becomes 1 or 0, then <code>SUM</code> adds them up. This "conditional count" is a very common interview pattern.</p><div class="callout amber"><div class="callout-title">Remember</div><p>End every <code>CASE</code> with <code>END</code>. Conditions are checked top to bottom, so put the strictest first.</p></div></div></div>`, '3'),
      block('Window functions: ROW_NUMBER, RANK, DENSE_RANK', 'Calculate across related rows without collapsing them into one.', `<div class="jgrid j2"><div class="jcard "><h4>Three ways to number rows</h4><p class="jsub">Same data, sorted by salary (highest first).</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT name, salary,
  ROW_NUMBER() OVER (ORDER BY salary DESC) AS row_num,
  RANK()       OVER (ORDER BY salary DESC) AS rnk,
  DENSE_RANK() OVER (ORDER BY salary DESC) AS dense
FROM employees;</code></pre></div><p><code>OVER (ORDER BY …)</code> says <em>"number the rows in this order"</em>. The columns before it are the function; <code>OVER</code> is what makes it a window function.</p></div><div class="jcard "><h4>Result: watch the ties</h4><p class="jsub">Ravi and Meena tie at 80000. Divya and Neha tie at 70000.</p><div class="tv"><div class="tv-head">result<small>8 rows</small></div><div class="tv-scroll"><table><thead><tr><th>name</th><th>salary</th><th>row_num</th><th>rnk</th><th>dense</th></tr></thead><tbody><tr><td>Asha</td><td>90000</td><td>1</td><td>1</td><td>1</td></tr><tr class="hl"><td>Ravi</td><td>80000</td><td>2</td><td>2</td><td>2</td></tr><tr class="hl"><td>Meena</td><td>80000</td><td>3</td><td>2</td><td>2</td></tr><tr class="hl"><td>Divya</td><td>70000</td><td>4</td><td>4</td><td>3</td></tr><tr class="hl"><td>Neha</td><td>70000</td><td>5</td><td>4</td><td>3</td></tr><tr><td>Sana</td><td>65000</td><td>6</td><td>6</td><td>4</td></tr><tr><td>Kiran</td><td>60000</td><td>7</td><td>7</td><td>5</td></tr><tr><td>Arjun</td><td>50000</td><td>8</td><td>8</td><td>6</td></tr></tbody></table></div></div><p class="jnote">Rows with equal salary may swap their <code>row_num</code>. Add a second sort column (like <code>name</code>) to make it fixed.</p></div></div><div class="jcard"><table class="tbl"><thead><tr><th>Function</th><th>Ties get</th><th>After a tie</th><th>Sequence here</th><th>Use it for</th></tr></thead><tbody><tr><td><code>ROW_NUMBER()</code></td><td>different numbers</td><td>carries on</td><td>1, 2, 3, 4, 5, 6…</td><td>exactly N rows, remove duplicates</td></tr><tr><td><code>RANK()</code></td><td>the <strong>same</strong> rank</td><td><strong>skips</strong> numbers</td><td>1, 2, 2, 4, 4, 6…</td><td>sports-style ranking</td></tr><tr><td><code>DENSE_RANK()</code></td><td>the <strong>same</strong> rank</td><td>no gap</td><td>1, 2, 2, 3, 3, 4…</td><td>"Nth highest" questions</td></tr></tbody></table></div>`, '4'),
      block('PARTITION BY and OVER', 'OVER defines the window. PARTITION BY splits it into groups, like GROUP BY but every row stays.', `<div class="jgrid j2"><div class="jcard "><h4>Rank inside each department</h4><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT name, dept, salary,
  RANK() OVER (
    PARTITION BY dept
    ORDER BY salary DESC
  ) AS dept_rank,
  ROUND(AVG(salary) OVER (
    PARTITION BY dept), 2) AS dept_avg
FROM employees
ORDER BY dept, dept_rank, name;</code></pre></div><ul class="jbul"><li><code>PARTITION BY dept</code> = start counting again for each department.</li><li><code>ORDER BY salary DESC</code> inside <code>OVER</code> = the order used for ranking.</li><li><code>AVG(…) OVER (…)</code> = an ordinary aggregate that is shown on every row instead of collapsing them.</li></ul></div><div class="jcard "><h4>Result</h4><div class="tv"><div class="tv-head">result<small>8 rows</small></div><div class="tv-scroll"><table><thead><tr><th>name</th><th>dept</th><th>salary</th><th>dept_rank</th><th>dept_avg</th></tr></thead><tbody><tr><td>Asha</td><td>Eng</td><td>90000</td><td>1</td><td>83333.33</td></tr><tr><td>Meena</td><td>Eng</td><td>80000</td><td>2</td><td>83333.33</td></tr><tr><td>Ravi</td><td>Eng</td><td>80000</td><td>2</td><td>83333.33</td></tr><tr><td>Divya</td><td>Sales</td><td>70000</td><td>1</td><td>66666.67</td></tr><tr><td>Neha</td><td>Sales</td><td>70000</td><td>1</td><td>66666.67</td></tr><tr><td>Kiran</td><td>Sales</td><td>60000</td><td>3</td><td>66666.67</td></tr><tr><td>Sana</td><td>HR</td><td>65000</td><td>1</td><td>57500.00</td></tr><tr><td>Arjun</td><td>HR</td><td>50000</td><td>2</td><td>57500.00</td></tr></tbody></table></div></div></div></div><div class="jcard"><table class="tbl"><thead><tr><th></th><th>GROUP BY</th><th>Window function (OVER)</th></tr></thead><tbody><tr><td>Rows in the result</td><td>one per group (collapsed)</td><td><strong>all rows kept</strong></td></tr><tr><td>Group total next to each row?</td><td>No, needs a join back</td><td>Yes, same query</td></tr><tr><td>Syntax</td><td><code>GROUP BY dept</code></td><td><code>… OVER (PARTITION BY dept)</code></td></tr></tbody></table></div>`, '5'),
      block('LAG and LEAD', 'Look at the previous row (LAG) or the next row (LEAD) without a self join.', `<div class="jgrid j2"><div class="jcard "><h4>Month-by-month change</h4><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT month, signups,
  LAG(signups)  OVER (ORDER BY month) AS prev,
  LEAD(signups) OVER (ORDER BY month) AS next,
  signups - LAG(signups)
    OVER (ORDER BY month)  AS change
FROM signups;</code></pre></div><ul class="jbul"><li><code>LAG(col)</code> = the value from the row <strong>before</strong>.</li><li><code>LEAD(col)</code> = the value from the row <strong>after</strong>.</li><li>The first row has no previous row, so <code>LAG</code> gives NULL. Pick a default with <code>LAG(col, 1, 0)</code>.</li><li>Add <code>PARTITION BY</code> to do this separately per user, per product…</li></ul></div><div class="jcard "><h4>Result</h4><p class="jsub">Source table and answer.</p><div class="tv"><div class="tv-head">signups<small>4 rows</small></div><div class="tv-scroll"><table><thead><tr><th>month</th><th>signups</th></tr></thead><tbody><tr><td>2026-01</td><td>100</td></tr><tr><td>2026-02</td><td>150</td></tr><tr><td>2026-03</td><td>120</td></tr><tr><td>2026-04</td><td>180</td></tr></tbody></table></div></div><div class="tv"><div class="tv-head">result<small>4 rows</small></div><div class="tv-scroll"><table><thead><tr><th>month</th><th>signups</th><th>prev</th><th>next</th><th>change</th></tr></thead><tbody><tr><td>2026-01</td><td>100</td><td><span class="tv-null">NULL</span></td><td>150</td><td><span class="tv-null">NULL</span></td></tr><tr><td>2026-02</td><td>150</td><td>100</td><td>120</td><td>50</td></tr><tr><td>2026-03</td><td>120</td><td>150</td><td>180</td><td>-30</td></tr><tr><td>2026-04</td><td>180</td><td>120</td><td><span class="tv-null">NULL</span></td><td>60</td></tr></tbody></table></div></div></div></div>`, '6'),
      block('UNION, UNION ALL, INTERSECT', 'Stack the results of two queries on top of each other.', `<div class="jband"><div class="jband-t"><strong>Two lists</strong><span>Who uses the iOS app and who uses the Android app. Ravi and Meena use both.</span></div><div class="tv-grid"><div class="tv"><div class="tv-head">ios_users<small>3 rows</small></div><div class="tv-scroll"><table><thead><tr><th>name</th></tr></thead><tbody><tr><td>Asha</td></tr><tr><td>Ravi</td></tr><tr><td>Meena</td></tr></tbody></table></div></div><div class="tv"><div class="tv-head">android_users<small>3 rows</small></div><div class="tv-scroll"><table><thead><tr><th>name</th></tr></thead><tbody><tr><td>Ravi</td></tr><tr><td>Kiran</td></tr><tr><td>Meena</td></tr></tbody></table></div></div></div></div><div class="jgrid j3"><div class="jcard "><h4>UNION</h4><p class="jsub">Everyone, duplicates removed.</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT name FROM ios_users
UNION
SELECT name FROM android_users;</code></pre></div><div class="tv"><div class="tv-head">result<small>4 rows</small></div><div class="tv-scroll"><table><thead><tr><th>name</th></tr></thead><tbody><tr><td>Asha</td></tr><tr><td>Ravi</td></tr><tr><td>Meena</td></tr><tr><td>Kiran</td></tr></tbody></table></div></div></div><div class="jcard "><h4>UNION ALL</h4><p class="jsub">Everyone, duplicates kept.</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT name FROM ios_users
UNION ALL
SELECT name FROM android_users;</code></pre></div><div class="tv"><div class="tv-head">result<small>6 rows</small></div><div class="tv-scroll"><table><thead><tr><th>name</th></tr></thead><tbody><tr><td>Asha</td></tr><tr><td>Ravi</td></tr><tr><td>Meena</td></tr><tr class="hl"><td>Ravi</td></tr><tr><td>Kiran</td></tr><tr class="hl"><td>Meena</td></tr></tbody></table></div></div></div><div class="jcard "><h4>INTERSECT</h4><p class="jsub">Only rows that appear in both.</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT name FROM ios_users
INTERSECT
SELECT name FROM android_users;</code></pre></div><div class="tv"><div class="tv-head">result<small>2 rows</small></div><div class="tv-scroll"><table><thead><tr><th>name</th></tr></thead><tbody><tr><td>Ravi</td></tr><tr><td>Meena</td></tr></tbody></table></div></div></div></div><div class="jgrid j2"><div class="jcard "><h4>Rules</h4><ul class="jbul"><li>Both queries need the <strong>same number of columns</strong>, with compatible types.</li><li>Column names come from the <strong>first</strong> query.</li><li><code>ORDER BY</code> goes once, at the very end.</li><li><code>EXCEPT</code> (rows in the first but not the second) also exists: it would give Asha.</li></ul></div><div class="jcard "><h4>UNION vs UNION ALL</h4><div class="callout green"><div class="callout-title">Prefer UNION ALL</div><p><code>UNION</code> has to sort or hash everything to remove duplicates, which costs time. If duplicates are impossible or acceptable, use <code>UNION ALL</code>. It is faster.</p></div></div></div>`, '7'),
      block('Second-highest salary and top N per group', 'Two classic interview questions. Ask "what about ties?" before you answer.', `<h4>Second-highest salary: three ways</h4><div class="jgrid j3"><div class="jcard "><h4>1. DENSE_RANK</h4><p class="jsub">Handles ties correctly. Works for "Nth".</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT DISTINCT salary
FROM (
  SELECT salary,
    DENSE_RANK() OVER (
      ORDER BY salary DESC) AS r
  FROM employees
) t
WHERE r = 2;</code></pre></div><div class="tv"><div class="tv-head">result<small>1 row</small></div><div class="tv-scroll"><table><thead><tr><th>salary</th></tr></thead><tbody><tr><td>80000</td></tr></tbody></table></div></div></div><div class="jcard "><h4>2. Subquery with MAX</h4><p class="jsub">Short, but only for the 2nd.</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT MAX(salary)
FROM employees
WHERE salary &lt; (
  SELECT MAX(salary)
  FROM employees
);</code></pre></div><div class="tv"><div class="tv-head">result<small>1 row</small></div><div class="tv-scroll"><table><thead><tr><th>MAX(salary)</th></tr></thead><tbody><tr><td>80000</td></tr></tbody></table></div></div><p class="jnote">The biggest salary smaller than the biggest.</p></div><div class="jcard "><h4>3. LIMIT … OFFSET</h4><p class="jsub">Easy. Needs DISTINCT for ties.</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT DISTINCT salary
FROM employees
ORDER BY salary DESC
LIMIT 1 OFFSET 1;</code></pre></div><div class="tv"><div class="tv-head">result<small>1 row</small></div><div class="tv-scroll"><table><thead><tr><th>salary</th></tr></thead><tbody><tr><td>80000</td></tr></tbody></table></div></div><p class="jnote">Without <code>DISTINCT</code>, two people on the top salary would make the "second" row still the top salary.</p></div></div><div class="callout green"><div class="callout-title">Who has it?</div><p>To get the <em>names</em>, use the DENSE_RANK version and select <code>name, salary</code> where <code>r = 2</code>. It returns Ravi and Meena, since both earn 80000.</p></div><h4>Top N per group: top 2 earners in each department</h4><div class="jgrid j2"><div class="jcard "><h4>The pattern</h4><p class="jsub">Number the rows inside each group, then keep the first N.</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT name, dept, salary, rn
FROM (
  SELECT name, dept, salary,
    ROW_NUMBER() OVER (
      PARTITION BY dept
      ORDER BY salary DESC, name
    ) AS rn
  FROM employees
) t
WHERE rn &lt;= 2;</code></pre></div><ol class="tv-steps"><li>Number rows inside each department, highest salary first (<code>ROW_NUMBER … PARTITION BY dept</code>).</li><li>Wrap that in a subquery or CTE.</li><li>Filter <code>rn &lt;= 2</code> in the outer query.</li></ol></div><div class="jcard "><h4>Result</h4><div class="tv"><div class="tv-head">result<small>6 rows</small></div><div class="tv-scroll"><table><thead><tr><th>name</th><th>dept</th><th>salary</th><th>rn</th></tr></thead><tbody><tr><td>Asha</td><td>Eng</td><td>90000</td><td>1</td></tr><tr><td>Meena</td><td>Eng</td><td>80000</td><td>2</td></tr><tr><td>Divya</td><td>Sales</td><td>70000</td><td>1</td></tr><tr><td>Neha</td><td>Sales</td><td>70000</td><td>2</td></tr><tr><td>Sana</td><td>HR</td><td>65000</td><td>1</td></tr><tr><td>Arjun</td><td>HR</td><td>50000</td><td>2</td></tr></tbody></table></div></div><div class="callout amber"><div class="callout-title">Two things to remember</div><p><strong>1.</strong> You cannot filter on a window function in the same <code>WHERE</code>, so the subquery or CTE is required. <strong>2.</strong> <code>ROW_NUMBER</code> gives <em>exactly</em> N rows per group. Use <code>RANK</code> or <code>DENSE_RANK</code> if people tied for N should all appear.</p></div></div></div>`, '8'),
      block('Cheat sheet', 'Pick the tool from the question.', `<div class="jcard"><table class="tbl"><thead><tr><th>I need…</th><th>Use</th></tr></thead><tbody><tr><td>A value from another query to compare against</td><td>Subquery in <code>WHERE</code></td></tr><tr><td>A comparison that depends on each row's own group</td><td>Correlated subquery, or a window function</td></tr><tr><td>A long query broken into readable steps</td><td><code>WITH … AS (…)</code></td></tr><tr><td>If-else logic, or a conditional count</td><td><code>CASE WHEN … THEN … ELSE … END</code></td></tr><tr><td>A number for each row in order (unique)</td><td><code>ROW_NUMBER()</code></td></tr><tr><td>Ranking with ties</td><td><code>RANK()</code> (gaps) or <code>DENSE_RANK()</code> (no gaps)</td></tr><tr><td>A total or rank per group but all rows kept</td><td><code>… OVER (PARTITION BY …)</code></td></tr><tr><td>The previous or next row's value</td><td><code>LAG()</code> / <code>LEAD()</code></td></tr><tr><td>Combine two result sets</td><td><code>UNION ALL</code> (keep duplicates), <code>UNION</code> (remove), <code>INTERSECT</code> (common)</td></tr><tr><td>Nth highest</td><td><code>DENSE_RANK() … = N</code></td></tr><tr><td>Top N per group</td><td><code>ROW_NUMBER() OVER (PARTITION BY …) … WHERE rn &lt;= N</code> in a subquery</td></tr></tbody></table></div>`, '9'),
    ],
  });

  /* ---------- 3.6 Indexing & Performance ---------- */
  subs.push({
    key: 'performance', title: 'Indexing & Performance', lead: 'Level 4: keys and indexes, B-trees, composite indexes, EXPLAIN, seq vs index scan, slow queries, OFFSET vs keyset pagination, N+1.',
    blocks: [
      block('Indexing and query performance', 'You should be able to explain why a query is slow and how you would investigate it. This page gives you the words and the steps.', `<ul class="topics"><li>Primary keys and foreign keys</li><li>Unique constraints and composite indexes</li><li>B-tree indexes and when they help</li><li>EXPLAIN and EXPLAIN ANALYZE</li><li>Sequential scan vs index scan</li><li>Why queries become slow</li><li>OFFSET vs keyset pagination</li><li>N+1 query problems</li></ul><div class="jband"><div class="jband-t"><strong>Our example</strong><span>A big <code>posts</code> table. Nothing is stored in the examples below, we just imagine the size.</span></div><div class="tv-grid"><div class="jcard" style="min-width:320px"><table class="tbl"><thead><tr><th>Table</th><th>Rows</th><th>Columns</th></tr></thead><tbody><tr><td><code>users</code></td><td>50,000</td><td><code>user_id</code> (PK), <code>username</code>, <code>email</code></td></tr><tr><td><code>posts</code></td><td><strong>1,000,000</strong></td><td><code>post_id</code> (PK), <code>user_id</code> (FK), <code>caption</code>, <code>created_at</code></td></tr></tbody></table></div></div></div>`),
      block('Primary keys, foreign keys and unique constraints', 'A constraint is a rule. An index is a speed tool. Some constraints give you both.', `<div class="jgrid j2"><div class="jcard "><h4>What you declare, what you get</h4><table class="tbl"><thead><tr><th>You declare</th><th>The database also builds</th><th>Note</th></tr></thead><tbody><tr><td><code>PRIMARY KEY</code></td><td>a unique index</td><td>Also NOT NULL. Lookups by <code>post_id</code> are fast by default.</td></tr><tr><td><code>UNIQUE</code></td><td>a unique index</td><td>Blocks duplicates and speeds up lookups on that column.</td></tr><tr><td><code>FOREIGN KEY</code></td><td><strong>nothing</strong> in PostgreSQL</td><td>MySQL (InnoDB) does index it. In PostgreSQL, add the index yourself.</td></tr><tr><td><code>PRIMARY KEY (a, b)</code></td><td>one index on <code>(a, b)</code></td><td>Order matters. See composite indexes.</td></tr></tbody></table></div><div class="jcard "><h4>Index your foreign keys</h4><p class="jsub"><code>posts.user_id</code> is a foreign key.</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>CREATE INDEX idx_posts_user_id
  ON posts (user_id);</code></pre></div><ul class="jbul"><li>"Show all posts of user 42" filters on <code>user_id</code>. Without an index it reads the whole table.</li><li>Joining <code>users</code> to <code>posts</code> uses the same column.</li><li>Deleting a user makes the database look for that user's posts, so it needs the index too.</li></ul></div></div><div class="callout green"><div class="callout-title">Remember</div><p>Primary key and unique give you a rule <em>and</em> an index. A foreign key gives you a rule only (in PostgreSQL), so create its index on purpose.</p></div>`, '1'),
      block('B-tree indexes and when indexes help', 'The default index type. Think of the index at the back of a book.', `<div class="jgrid j2"><div class="jcard "><h4>How it works</h4><p>A B-tree keeps the values <strong>sorted</strong> in a small tree. To find 60 you do not read every row. You ask the root, then one node, then you reach the row.</p><ul class="jbul"><li>Looking for <strong>60</strong>: the root says "between 40 and 80", go to the middle node, find 60, jump to the row.</li><li>A table of a million rows needs only about <strong>3 to 4 steps</strong>. Doubling the data adds almost nothing.</li><li>Because values are sorted, it also handles ranges (<code>BETWEEN</code>, <code>&gt;</code>) and <code>ORDER BY</code>.</li></ul><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>CREATE INDEX idx_posts_created_at
  ON posts (created_at);</code></pre></div></div><div class="jcard "><h4>Looking for 60</h4><p class="jsub">Green path: root → middle node → row.</p><div class="jfig"><svg viewBox="0 0 560 240" style="width:100%;height:auto" role="img" aria-label="A B-tree: searching for 60 goes root, middle node, then the row" font-family="Inter, system-ui, Arial, sans-serif"><line x1="280" y1="44" x2="95" y2="90" stroke="#9b9b9b" stroke-width="1.4"/><line x1="280" y1="44" x2="465" y2="90" stroke="#9b9b9b" stroke-width="1.4"/><line x1="280" y1="44" x2="280" y2="90" stroke="#1e7a4c" stroke-width="2.6"/><rect x="215" y="10" width="130" height="34" rx="7" fill="#fff" stroke="#0d0d0d" stroke-width="1.5"/><text x="280" y="32" text-anchor="middle" font-size="13" font-weight="600" fill="#0d0d0d" font-family="ui-monospace, Consolas, monospace">40 · 80</text><rect x="20" y="90" width="150" height="34" rx="7" fill="#fff" stroke="#0d0d0d" stroke-width="1.5"/><text x="95" y="112" text-anchor="middle" font-size="13" font-weight="600" fill="#0d0d0d" font-family="ui-monospace, Consolas, monospace">10 · 20 · 30</text><line x1="95" y1="124" x2="44" y2="178" stroke="#9b9b9b" stroke-width="1.4"/><rect x="22" y="178" width="46" height="30" rx="7" fill="#fff" stroke="#0d0d0d" stroke-width="1.5"/><text x="45" y="198" text-anchor="middle" font-size="13" font-weight="600" fill="#0d0d0d" font-family="ui-monospace, Consolas, monospace">10</text><line x1="95" y1="124" x2="94" y2="178" stroke="#9b9b9b" stroke-width="1.4"/><rect x="72" y="178" width="46" height="30" rx="7" fill="#fff" stroke="#0d0d0d" stroke-width="1.5"/><text x="95" y="198" text-anchor="middle" font-size="13" font-weight="600" fill="#0d0d0d" font-family="ui-monospace, Consolas, monospace">20</text><line x1="95" y1="124" x2="144" y2="178" stroke="#9b9b9b" stroke-width="1.4"/><rect x="122" y="178" width="46" height="30" rx="7" fill="#fff" stroke="#0d0d0d" stroke-width="1.5"/><text x="145" y="198" text-anchor="middle" font-size="13" font-weight="600" fill="#0d0d0d" font-family="ui-monospace, Consolas, monospace">30</text><rect x="205" y="90" width="150" height="34" rx="7" fill="#e7f3ec" stroke="#1e7a4c" stroke-width="2.2"/><text x="280" y="112" text-anchor="middle" font-size="13" font-weight="600" fill="#0d0d0d" font-family="ui-monospace, Consolas, monospace">50 · 60 · 70</text><line x1="280" y1="124" x2="229" y2="178" stroke="#9b9b9b" stroke-width="1.4"/><rect x="207" y="178" width="46" height="30" rx="7" fill="#fff" stroke="#0d0d0d" stroke-width="1.5"/><text x="230" y="198" text-anchor="middle" font-size="13" font-weight="600" fill="#0d0d0d" font-family="ui-monospace, Consolas, monospace">50</text><line x1="280" y1="124" x2="279" y2="178" stroke="#1e7a4c" stroke-width="2.6"/><rect x="257" y="178" width="46" height="30" rx="7" fill="#e7f3ec" stroke="#1e7a4c" stroke-width="2.2"/><text x="280" y="198" text-anchor="middle" font-size="13" font-weight="600" fill="#0d0d0d" font-family="ui-monospace, Consolas, monospace">60</text><line x1="280" y1="124" x2="329" y2="178" stroke="#9b9b9b" stroke-width="1.4"/><rect x="307" y="178" width="46" height="30" rx="7" fill="#fff" stroke="#0d0d0d" stroke-width="1.5"/><text x="330" y="198" text-anchor="middle" font-size="13" font-weight="600" fill="#0d0d0d" font-family="ui-monospace, Consolas, monospace">70</text><rect x="390" y="90" width="150" height="34" rx="7" fill="#fff" stroke="#0d0d0d" stroke-width="1.5"/><text x="465" y="112" text-anchor="middle" font-size="13" font-weight="600" fill="#0d0d0d" font-family="ui-monospace, Consolas, monospace">90 · 100 · 110</text><line x1="465" y1="124" x2="414" y2="178" stroke="#9b9b9b" stroke-width="1.4"/><rect x="392" y="178" width="46" height="30" rx="7" fill="#fff" stroke="#0d0d0d" stroke-width="1.5"/><text x="415" y="198" text-anchor="middle" font-size="13" font-weight="600" fill="#0d0d0d" font-family="ui-monospace, Consolas, monospace">90</text><line x1="465" y1="124" x2="464" y2="178" stroke="#9b9b9b" stroke-width="1.4"/><rect x="442" y="178" width="46" height="30" rx="7" fill="#fff" stroke="#0d0d0d" stroke-width="1.5"/><text x="465" y="198" text-anchor="middle" font-size="13" font-weight="600" fill="#0d0d0d" font-family="ui-monospace, Consolas, monospace">100</text><line x1="465" y1="124" x2="514" y2="178" stroke="#9b9b9b" stroke-width="1.4"/><rect x="492" y="178" width="46" height="30" rx="7" fill="#fff" stroke="#0d0d0d" stroke-width="1.5"/><text x="515" y="198" text-anchor="middle" font-size="13" font-weight="600" fill="#0d0d0d" font-family="ui-monospace, Consolas, monospace">110</text><text x="10" y="34" font-size="11" fill="#6b6b6b">index</text><text x="10" y="232" font-size="11" fill="#6b6b6b">table rows (found at the bottom of the tree)</text></svg></div></div></div><div class="jgrid j2"><div class="jcard good"><h4>Indexes help with</h4><ul class="jbul"><li><code>WHERE col = value</code> and ranges (<code>&lt;</code>, <code>&gt;</code>, <code>BETWEEN</code>)</li><li><code>JOIN … ON</code> columns</li><li><code>ORDER BY col LIMIT n</code> (already sorted, no sorting needed)</li><li><code>MIN</code> / <code>MAX</code></li><li>Prefix search: <code>LIKE 'abc%'</code></li><li>Checking uniqueness quickly</li></ul></div><div class="jcard warn"><h4>Indexes do NOT help when</h4><ul class="jbul"><li>The table is tiny. Reading it all is already fast.</li><li>The column has few different values (like <code>is_active</code>, where 95% are true).</li><li>The pattern starts with a wildcard: <code>LIKE '%abc'</code>.</li><li>You wrap the column in a function or maths: <code>WHERE LOWER(email) = …</code>, <code>WHERE views + 1 = 10</code>.</li><li>You need most of the table anyway.</li><li>The types do not match (comparing a number column to a text value).</li></ul></div></div><div class="callout amber"><div class="callout-title">The price of an index</div><p>Every <code>INSERT</code>, <code>UPDATE</code> and <code>DELETE</code> must also update every index on that table, and indexes take disk space. Add indexes for queries you actually run, not "just in case".</p></div>`, '2'),
      block('Composite indexes', 'One index on several columns. Like a phone book sorted by last name, then first name.', `<div class="jgrid j2"><div class="jcard "><h4>Built for one query</h4><p class="jsub">"Latest posts of a user."</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>CREATE INDEX idx_posts_user_created
  ON posts (user_id, created_at);

SELECT * FROM posts
WHERE user_id = 42
ORDER BY created_at DESC
LIMIT 10;</code></pre></div><p class="jnote">The index is sorted by <code>user_id</code> first, then by <code>created_at</code> inside each user. The database jumps to user 42 and reads the newest entries in order.</p></div><div class="jcard "><h4>What the index looks like</h4><p class="jsub">Sorted by the first column, then the second.</p><div class="tv"><div class="tv-head">index (user_id, created_at)<small>5 rows</small></div><div class="tv-scroll"><table><thead><tr><th>user_id</th><th>created_at</th><th>→ row</th></tr></thead><tbody><tr><td>1</td><td>Jan 05</td><td>post 101</td></tr><tr><td>1</td><td>Mar 02</td><td>post 103</td></tr><tr><td>2</td><td>Feb 01</td><td>post 102</td></tr><tr><td>2</td><td>Feb 09</td><td>post 105</td></tr><tr><td>3</td><td>Jan 20</td><td>post 104</td></tr></tbody></table></div></div></div></div><div class="jgrid j2"><div class="jcard "><h4>The leftmost-column rule</h4><p class="jsub">The index works from the left. You cannot skip the first column.</p><table class="tbl"><thead><tr><th>Query filters on</th><th>Uses the index?</th></tr></thead><tbody><tr><td><code>user_id</code></td><td>Yes</td></tr><tr><td><code>user_id</code> and <code>created_at</code></td><td>Yes, best case</td></tr><tr><td><code>user_id</code> + <code>ORDER BY created_at</code></td><td>Yes, and no extra sort</td></tr><tr><td><code>created_at</code> only</td><td><strong>No</strong> (or poorly). It skips the first column</td></tr></tbody></table></div><div class="jcard "><h4>Choosing the column order</h4><ul class="jbul"><li>Put columns tested with <strong>equals</strong> first.</li><li>Put the <strong>range or sort</strong> column last.</li><li>One composite index usually replaces a separate index on its first column.</li></ul><p class="jnote">Phone book: easy to find "Sharma", hard to find everyone called "Asha" (the second column) without reading the whole book.</p></div></div>`, '3'),
      block('Sequential scan vs index scan', 'Two ways the database can find your rows. It chooses the cheaper one.', `<div class="jgrid j2"><div class="jcard "><h4>Sequential scan (Seq Scan)</h4><p class="jsub">Reads <strong>every page</strong> of the table and keeps the matches.</p><div class="jfig"><svg viewBox="0 0 384 128" style="width:100%;max-width:400px;height:auto" role="img" aria-label="Every page of the table is read"><rect x="2" y="2" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="34" y="2" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="66" y="2" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="98" y="2" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="130" y="2" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="162" y="2" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="194" y="2" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="226" y="2" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="258" y="2" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="290" y="2" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="322" y="2" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="354" y="2" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="2" y="34" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="34" y="34" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="66" y="34" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="98" y="34" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="130" y="34" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="162" y="34" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="194" y="34" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="226" y="34" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="258" y="34" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="290" y="34" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="322" y="34" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="354" y="34" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="2" y="66" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="34" y="66" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="66" y="66" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="98" y="66" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="130" y="66" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="162" y="66" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="194" y="66" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="226" y="66" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="258" y="66" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="290" y="66" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="322" y="66" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="354" y="66" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="2" y="98" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="34" y="98" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="66" y="98" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="98" y="98" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="130" y="98" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="162" y="98" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="194" y="98" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="226" y="98" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="258" y="98" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="290" y="98" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="322" y="98" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/><rect x="354" y="98" width="26" height="26" rx="5" fill="#cfe7da" stroke="#1e7a4c" stroke-width="1.4"/></svg></div><ul class="jbul"><li>Work grows with the size of the table.</li><li>Fine for small tables, or when you need most of the rows.</li><li>The classic sign of a missing index on a big table.</li></ul></div><div class="jcard "><h4>Index scan</h4><p class="jsub">Uses the index to <strong>jump</strong> to the few pages that hold the rows.</p><div class="jfig"><svg viewBox="0 0 384 128" style="width:100%;max-width:400px;height:auto" role="img" aria-label="Only a few pages are read"><rect x="2" y="2" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="34" y="2" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="66" y="2" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="98" y="2" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="130" y="2" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="162" y="2" width="26" height="26" rx="5" fill="#1e7a4c" stroke="#1e7a4c" stroke-width="1.4"/><rect x="194" y="2" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="226" y="2" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="258" y="2" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="290" y="2" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="322" y="2" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="354" y="2" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="2" y="34" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="34" y="34" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="66" y="34" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="98" y="34" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="130" y="34" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="162" y="34" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="194" y="34" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="226" y="34" width="26" height="26" rx="5" fill="#1e7a4c" stroke="#1e7a4c" stroke-width="1.4"/><rect x="258" y="34" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="290" y="34" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="322" y="34" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="354" y="34" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="2" y="66" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="34" y="66" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="66" y="66" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="98" y="66" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="130" y="66" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="162" y="66" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="194" y="66" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="226" y="66" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="258" y="66" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="290" y="66" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="322" y="66" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="354" y="66" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="2" y="98" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="34" y="98" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="66" y="98" width="26" height="26" rx="5" fill="#1e7a4c" stroke="#1e7a4c" stroke-width="1.4"/><rect x="98" y="98" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="130" y="98" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="162" y="98" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="194" y="98" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="226" y="98" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="258" y="98" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="290" y="98" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="322" y="98" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/><rect x="354" y="98" width="26" height="26" rx="5" fill="#f3f3f1" stroke="#dcdcd8" stroke-width="1.4"/></svg></div><ul class="jbul"><li>Work stays small even on huge tables.</li><li>Best when the query returns only a few rows.</li><li>Related: <em>Index Only Scan</em> (the index has all the columns you need) and <em>Bitmap Scan</em> (a middle ground).</li></ul></div></div><div class="callout green"><div class="callout-title">An index does not guarantee an index scan</div><p>If a query returns a big share of the table, the database may <em>choose</em> a seq scan on purpose, because jumping around is slower than reading in order. It decides from statistics about your data, which is why <code>EXPLAIN</code> matters.</p></div>`, '4'),
      block('EXPLAIN and EXPLAIN ANALYZE', 'Ask the database how it will run, or did run, a query.', `<div class="jgrid j2"><div class="jcard "><h4>The two commands</h4><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>EXPLAIN
SELECT * FROM posts WHERE user_id = 42;

EXPLAIN ANALYZE
SELECT * FROM posts WHERE user_id = 42;</code></pre></div><table class="tbl"><thead><tr><th></th><th>EXPLAIN</th><th>EXPLAIN ANALYZE</th></tr></thead><tbody><tr><td>Runs the query?</td><td>No</td><td><strong>Yes</strong></td></tr><tr><td>Numbers</td><td>estimates</td><td>estimates <strong>and</strong> real time and rows</td></tr></tbody></table><div class="callout amber"><div class="callout-title">Careful</div><p><code>EXPLAIN ANALYZE</code> really executes the query. For <code>UPDATE</code> or <code>DELETE</code>, wrap it: <code>BEGIN; EXPLAIN ANALYZE …; ROLLBACK;</code></p></div></div><div class="jcard "><h4>Before the index</h4><p class="jsub">Example output (PostgreSQL). Numbers are illustrative.</p><div class="code"><div class="code-bar">output</div><pre><code>Seq Scan on posts  (cost=0.00..21500.00 rows=3 width=72)
                   (actual time=0.020..96.310 rows=3 loops=1)
  Filter: (user_id = 42)
  Rows Removed by Filter: 999997
Planning Time: 0.090 ms
Execution Time: 96.350 ms</code></pre></div><p class="jsub" style="margin-top:14px">After <code>CREATE INDEX idx_posts_user_id ON posts (user_id);</code></p><div class="code"><div class="code-bar">output</div><pre><code>Index Scan using idx_posts_user_id on posts
    (cost=0.42..12.50 rows=3 width=72)
    (actual time=0.030..0.045 rows=3 loops=1)
  Index Cond: (user_id = 42)
Planning Time: 0.110 ms
Execution Time: 0.070 ms</code></pre></div></div></div><div class="jcard "><h4>How to read a plan</h4><p class="jsub">Look at these first.</p><table class="tbl"><thead><tr><th>You see</th><th>It means</th></tr></thead><tbody><tr><td><code>Seq Scan on posts</code></td><td>The whole table is read. Suspicious on a big table.</td></tr><tr><td><code>Rows Removed by Filter: 999997</code></td><td>Almost everything read was thrown away. An index could avoid that work.</td></tr><tr><td><code>Index Scan using idx_…</code> / <code>Index Cond</code></td><td>The index was used.</td></tr><tr><td><code>cost=0.00..21500.00</code></td><td>The planner's estimate in made-up units, only good for comparing plans.</td></tr><tr><td><code>rows=3</code> vs <code>actual … rows=3</code></td><td>Estimated vs real rows. A big gap means stale statistics. Run <code>ANALYZE</code>.</td></tr><tr><td><code>actual time</code> and <code>Execution Time</code></td><td>Real milliseconds. The number you want to bring down.</td></tr></tbody></table></div>`, '5'),
      block('Why queries become slow', 'Most slow queries have one of a few common causes.', `<div class="jgrid j2"><div class="jcard "><h4>Common causes and fixes</h4><table class="tbl"><thead><tr><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>No index on the filter or join column</td><td>Add an index</td></tr><tr><td>Function or maths on the column (<code>LOWER(email)</code>)</td><td>Rewrite, or create an index on the expression</td></tr><tr><td><code>LIKE '%abc'</code> (leading wildcard)</td><td>Full-text search or a trigram index</td></tr><tr><td><code>SELECT *</code> when you need 2 columns</td><td>Select only what you need</td></tr><tr><td>Big <code>OFFSET</code></td><td>Keyset pagination</td></tr><tr><td>N+1 queries</td><td>Join or batch the queries</td></tr><tr><td>Returning far too many rows</td><td>Filter, <code>LIMIT</code>, paginate</td></tr><tr><td>Composite index in the wrong column order</td><td>Reorder the columns</td></tr><tr><td>Outdated statistics</td><td><code>ANALYZE</code></td></tr><tr><td>Too many indexes (slow writes)</td><td>Drop the ones nobody uses</td></tr><tr><td>Waiting on another transaction's lock</td><td>Keep transactions short</td></tr></tbody></table></div><div class="jcard "><h4>How to investigate, step by step</h4><ol class="tv-steps">
          <li><strong>Find the query.</strong> Use the slow-query log or <code>pg_stat_statements</code>. Get the real parameter values.</li>
          <li><strong>Run <code>EXPLAIN ANALYZE</code></strong> on it.</li>
          <li><strong>Look for</strong> a Seq Scan on a big table, huge <em>Rows Removed by Filter</em>, a big gap between estimated and actual rows, or an expensive sort.</li>
          <li><strong>Make a guess:</strong> "there is no index on <code>user_id</code>".</li>
          <li><strong>Fix it:</strong> add the index or rewrite the query.</li>
          <li><strong>Run <code>EXPLAIN ANALYZE</code> again.</strong> Confirm the plan changed and the time dropped.</li>
          <li><strong>Check the cost:</strong> make sure writes did not get noticeably slower.</li>
        </ol></div></div>`, '6'),
      block('Pagination: OFFSET vs keyset', 'Both give you "the next 20 rows". They behave very differently on page 5,000.', `<div class="jgrid j2"><div class="jcard "><h4>OFFSET pagination</h4><p class="jsub">Simple, but gets slower on every page.</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT post_id, caption
FROM posts
ORDER BY post_id DESC
LIMIT 20 OFFSET 100000;</code></pre></div><p>To return 20 rows, the database must first <strong>walk past 100,000 rows and throw them away</strong>. The deeper the page, the more it skips.</p></div><div class="jcard "><h4>Keyset pagination</h4><p class="jsub">Remember the last row you showed, and start after it.</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT post_id, caption
FROM posts
WHERE post_id &lt; 900000   -- last id of the previous page
ORDER BY post_id DESC
LIMIT 20;</code></pre></div><p>The index jumps straight to <code>900000</code> and reads 20 rows. Page 1 and page 5,000 cost the same.</p></div></div><div class="jcard "><h4>Rows the database walks through (page size 20)</h4><div class="jbars"><div class="jbar-row"><span class="jbar-l">Page 1</span><div class="jbar-w"><div class="jbar"><i style="width:1.2%" class="amber"></i><span>20</span></div><div class="jbar"><i style="width:1.2%" class="green"></i><span>20</span></div></div></div><div class="jbar-row"><span class="jbar-l">Page 100</span><div class="jbar-w"><div class="jbar"><i style="width:2%" class="amber"></i><span>2,000</span></div><div class="jbar"><i style="width:1.2%" class="green"></i><span>20</span></div></div></div><div class="jbar-row"><span class="jbar-l">Page 5,000</span><div class="jbar-w"><div class="jbar"><i style="width:100%" class="amber"></i><span>100,000</span></div><div class="jbar"><i style="width:1.2%" class="green"></i><span>20</span></div></div></div></div><p class="jnote"><span class="jkey amber"></span> OFFSET &nbsp; <span class="jkey green"></span> keyset</p></div><div class="jgrid j2"><div class="jcard "><h4>Trade-offs</h4><table class="tbl"><thead><tr><th></th><th>OFFSET</th><th>Keyset</th></tr></thead><tbody><tr><td>Speed on deep pages</td><td>slow</td><td><strong>constant</strong></td></tr><tr><td>Jump to "page 500"</td><td>yes</td><td>no (next / previous only)</td></tr><tr><td>Rows shift when data changes</td><td>yes, you may see repeats or skips</td><td>stable</td></tr><tr><td>Needs</td><td>nothing</td><td>a unique, indexed sort column</td></tr></tbody></table></div><div class="jcard "><h4>Sorting by a non-unique column</h4><p class="jsub">Add the id as a tie-breaker and compare both together.</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT post_id, caption, created_at
FROM posts
WHERE (created_at, post_id)
    &lt; ('2026-10-01 10:00:00', 900000)
ORDER BY created_at DESC, post_id DESC
LIMIT 20;</code></pre></div><p class="jnote">Back it with an index on <code>(created_at, post_id)</code>. Your API returns a <code>next_cursor</code> (the last row's values) and the client sends it back.</p></div></div>`, '7'),
      block('The N+1 query problem', 'One query to get a list, then one extra query for each item in it.', `<div class="jgrid j2"><div class="jcard "><h4>How it happens</h4><p class="jsub">Show 20 posts with the author's name.</p><div class="code"><div class="code-bar">output</div><pre><code>const posts = await postRepo.find({ take: 20 });      // 1 query

for (const post of posts) {
  post.author = await userRepo.findOneBy({         // 20 queries
    user_id: post.user_id,
  });
}</code></pre></div><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT * FROM posts LIMIT 20;
SELECT * FROM users WHERE user_id = 1;
SELECT * FROM users WHERE user_id = 2;
SELECT * FROM users WHERE user_id = 1;
-- … 20 times in total</code></pre></div><p class="jnote"><strong>1 + 20 = 21 queries.</strong> With 100 posts it is 101. Each query pays for a network round trip, parsing and planning, so the page crawls.</p></div><div class="jcard "><h4>How to fix it</h4><h4>Fix 1: one JOIN (1 query)</h4><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT p.post_id, p.caption, u.username
FROM posts p
JOIN users u ON u.user_id = p.user_id
LIMIT 20;</code></pre></div><h4>Fix 2: batch with IN (2 queries)</h4><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>SELECT * FROM posts LIMIT 20;
SELECT * FROM users
WHERE user_id IN (1, 2, 3, 7, 9);</code></pre></div><h4>Fix 3: ask your ORM to load the relation</h4><table class="tbl"><thead><tr><th>ORM</th><th>Option</th></tr></thead><tbody><tr><td>TypeORM</td><td><code>relations: { author: true }</code></td></tr><tr><td>Prisma</td><td><code>include: { author: true }</code></td></tr><tr><td>Sequelize</td><td><code>include: [User]</code></td></tr></tbody></table></div></div><div class="callout green"><div class="callout-title">How to spot it</div><p>The query log shows the <strong>same query shape repeated with different ids</strong>, or the number of queries grows with the number of rows on the page. ORMs with lazy loading hide it well, so count the queries per request.</p></div>`, '8'),
      block('Say it in an interview', 'Your answer to "why is this query slow, and what would you do?"', `<div class="jgrid j2"><div class="jcard "><h4>A 30-second answer</h4><ol class="tv-steps"><li>"First I would get the exact query and run <strong>EXPLAIN ANALYZE</strong>."</li><li>"I would look for a <strong>sequential scan</strong> on a big table, many rows removed by the filter, or estimates far from actual."</li><li>"Usually it is a <strong>missing or unusable index</strong>, so I would add one, in the right column order, and check the plan again."</li><li>"If the query is fine, I would check for <strong>N+1</strong> calls, a deep <strong>OFFSET</strong>, or lock waits."</li></ol></div><div class="jcard "><h4>Quick definitions</h4><table class="tbl"><thead><tr><th>Term</th><th>One line</th></tr></thead><tbody><tr><td>Index</td><td>A sorted structure that lets the database jump to rows.</td></tr><tr><td>B-tree</td><td>The default index. Good for equals, ranges and sorting.</td></tr><tr><td>Seq scan</td><td>Read every page of the table.</td></tr><tr><td>Index scan</td><td>Use the index to jump to matching rows.</td></tr><tr><td>Composite index</td><td>An index on several columns. Leftmost column first.</td></tr><tr><td>EXPLAIN ANALYZE</td><td>Run the query and show the real plan and time.</td></tr><tr><td>Keyset pagination</td><td>"Start after the last row I saw." Constant speed.</td></tr><tr><td>N+1</td><td>One query for the list, plus one per item.</td></tr></tbody></table></div></div>`, '9'),
    ],
  });

  /* ---------- 3.7 Transactions & Design ---------- */
  subs.push({
    key: 'transactions', title: 'Transactions & Design', lead: 'Level 5: ACID, BEGIN / COMMIT / ROLLBACK, isolation levels, deadlocks, normalization, constraints and basic schema design.',
    blocks: [
      block('Transactions and database design', 'How a database keeps data correct when many things happen at once, and how to lay out tables so the data stays clean.', `<ul class="topics"><li>ACID properties</li><li>BEGIN, COMMIT, ROLLBACK</li><li>Isolation levels, dirty and non-repeatable reads</li><li>Deadlocks and locking basics</li><li>Normalization: 1NF, 2NF, 3NF</li><li>Constraints and data integrity</li><li>Basic schema design</li></ul><div class="jband"><div class="jband-t"><strong>Practice data</strong><span>A tiny bank. We will move money between these two accounts.</span></div><div class="tv-grid"><div class="tv"><div class="tv-head">accounts<small>2 rows</small></div><div class="tv-scroll"><table><thead><tr><th>id</th><th>owner</th><th>balance</th></tr></thead><tbody><tr><td>1</td><td>Asha</td><td>1000</td></tr><tr><td>2</td><td>Ravi</td><td>500</td></tr></tbody></table></div></div></div></div>`),
      block('Why we need transactions', 'Some changes only make sense together. A transaction makes a group of statements one single unit.', `<div class="jgrid j2"><div class="jcard "><h4>Sending money takes two steps</h4><p class="jsub">Move 200 from Asha to Ravi.</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>UPDATE accounts SET balance = balance - 200 WHERE id = 1;  -- Asha
UPDATE accounts SET balance = balance + 200 WHERE id = 2;  -- Ravi</code></pre></div><p>If the server crashes <strong>between</strong> the two lines, 200 rupees simply disappear. A transaction guarantees both lines happen, or neither does.</p></div><div class="jcard "><h4>What the balances look like</h4><p class="jsub">The total should always be 1500.</p><table class="tbl"><thead><tr><th>Moment</th><th>Asha</th><th>Ravi</th><th>Total</th></tr></thead><tbody><tr><td>Start</td><td>1000</td><td>500</td><td>1500</td></tr><tr><td><span class="jbad">After the first UPDATE, then a crash</span></td><td>800</td><td>500</td><td><strong>1300 ✗</strong></td></tr><tr><td>After both UPDATEs</td><td>800</td><td>700</td><td>1500</td></tr></tbody></table><p class="jnote">Row 2 is the dangerous state. Without a transaction, a crash can leave the database stuck there.</p></div></div>`, '1'),
      block('ACID properties', 'Four promises a transaction makes. The word is the first letters.', `<div class="jgrid j4"><div class="jcard "><h4><span class="jletter">A</span>Atomicity</h4><p class="jsub">All or nothing.</p><p>If any step fails, every step is undone. The transfer either fully happens or does not happen at all.</p><p class="jnote"><strong>Kept by:</strong> the undo log (rollback)</p></div><div class="jcard "><h4><span class="jletter">C</span>Consistency</h4><p class="jsub">Rules always hold.</p><p>Before and after, the data follows its rules: balance never negative, every post points to a real user.</p><p class="jnote"><strong>Kept by:</strong> constraints, plus your own logic</p></div><div class="jcard "><h4><span class="jletter">I</span>Isolation</h4><p class="jsub">No peeking at half-done work.</p><p>Other transactions running at the same time do not see the 1300 in the middle of the transfer.</p><p class="jnote"><strong>Kept by:</strong> locks and versions of rows, set by the isolation level</p></div><div class="jcard "><h4><span class="jletter">D</span>Durability</h4><p class="jsub">Committed means permanent.</p><p>Once the database says "committed", the change survives a crash or power cut.</p><p class="jnote"><strong>Kept by:</strong> the write-ahead log, flushed to disk</p></div></div>`, '2'),
      block('BEGIN, COMMIT, ROLLBACK', 'Three commands control a transaction.', `<div class="jgrid j2"><div class="jcard "><h4>Save it: COMMIT</h4><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>BEGIN;
UPDATE accounts SET balance = balance - 200 WHERE id = 1;
UPDATE accounts SET balance = balance + 200 WHERE id = 2;
COMMIT;</code></pre></div><p class="jnote">Until <code>COMMIT</code>, other users still see the old balances (1000 and 500). After it, both changes appear at once.</p></div><div class="jcard "><h4>Undo it: ROLLBACK</h4><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>BEGIN;
UPDATE accounts SET balance = balance - 200 WHERE id = 1;
-- something goes wrong here
ROLLBACK;</code></pre></div><p class="jnote">Everything since <code>BEGIN</code> is thrown away. Asha still has 1000.</p></div></div><div class="jgrid j2"><div class="jcard "><h4>The commands</h4><table class="tbl"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>BEGIN</code></td><td>Start a transaction</td></tr><tr><td><code>COMMIT</code></td><td>Make all changes permanent</td></tr><tr><td><code>ROLLBACK</code></td><td>Undo all changes since <code>BEGIN</code></td></tr><tr><td><code>SAVEPOINT name</code></td><td>A bookmark inside a transaction, so you can undo only part of it</td></tr></tbody></table><p class="jnote"><strong>Autocommit:</strong> without <code>BEGIN</code>, every single statement is its own mini transaction and is saved immediately.</p></div><div class="jcard "><h4>In a NestJS app</h4><p class="jsub">Let the ORM commit or roll back for you.</p><div class="code"><div class="code-bar">output</div><pre><code>await dataSource.transaction(async (manager) =&gt; {
  await manager.decrement(Account, { id: 1 }, 'balance', 200);
  await manager.increment(Account, { id: 2 }, 'balance', 200);
});   // an error inside = automatic ROLLBACK</code></pre></div><p class="jnote">Use the <code>manager</code> given to you for every query inside, or those queries run <em>outside</em> the transaction.</p></div></div>`, '3'),
      block('Isolation levels and the three problems', 'When transactions overlap, three strange things can happen. Isolation levels decide which ones you allow.', `<div class="jgrid j2"><div class="jcard "><h4>Dirty read</h4><p class="jsub">Reading someone's <strong>uncommitted</strong> change.</p><table class="jtime"><thead><tr><th>#</th><th>Transaction A</th><th>Transaction B</th><th>What happens</th></tr></thead><tbody><tr><td>1</td><td><code>UPDATE … SET balance = 0</code></td><td></td><td>A changes the balance but has not committed.</td></tr><tr><td>2</td><td></td><td><code>SELECT balance</code></td><td>B reads <strong>0</strong>, a value that is not official yet.</td></tr><tr><td>3</td><td><code>ROLLBACK</code></td><td></td><td>A undoes it. The balance is 1000, but B already used 0.</td></tr></tbody></table></div><div class="jcard "><h4>Non-repeatable read</h4><p class="jsub">The <strong>same row</strong> changes between two reads.</p><table class="jtime"><thead><tr><th>#</th><th>Transaction A</th><th>Transaction B</th><th>What happens</th></tr></thead><tbody><tr><td>1</td><td><code>SELECT balance</code></td><td></td><td>A reads <strong>1000</strong>.</td></tr><tr><td>2</td><td></td><td><code>UPDATE … SET balance = 800; COMMIT</code></td><td>B changes it and commits.</td></tr><tr><td>3</td><td><code>SELECT balance</code></td><td></td><td>A reads <strong>800</strong>. Same query, different answer.</td></tr></tbody></table></div></div><div class="jgrid j2"><div class="jcard "><h4>Phantom read</h4><p class="jsub">The <strong>set of rows</strong> changes between two reads.</p><table class="jtime"><thead><tr><th>#</th><th>Transaction A</th><th>Transaction B</th><th>What happens</th></tr></thead><tbody><tr><td>1</td><td><code>SELECT COUNT(*) … user_id = 1</code></td><td></td><td>A sees <strong>2</strong> posts.</td></tr><tr><td>2</td><td></td><td><code>INSERT a post for user 1; COMMIT</code></td><td>B adds a matching row.</td></tr><tr><td>3</td><td><code>SELECT COUNT(*) … user_id = 1</code></td><td></td><td>A now sees <strong>3</strong>. A "phantom" appeared.</td></tr></tbody></table></div><div class="jcard "><h4>Which level allows which problem</h4><table class="tbl"><thead><tr><th>Isolation level</th><th>Dirty read</th><th>Non-repeatable read</th><th>Phantom read</th></tr></thead><tbody><tr><td>Read Uncommitted</td><td><span class="jyes">Possible</span></td><td><span class="jyes">Possible</span></td><td><span class="jyes">Possible</span></td></tr><tr><td>Read Committed</td><td><span class="jno">Prevented</span></td><td><span class="jyes">Possible</span></td><td><span class="jyes">Possible</span></td></tr><tr><td>Repeatable Read</td><td><span class="jno">Prevented</span></td><td><span class="jno">Prevented</span></td><td><span class="jyes">Possible</span> <small>*</small></td></tr><tr><td>Serializable</td><td><span class="jno">Prevented</span></td><td><span class="jno">Prevented</span></td><td><span class="jno">Prevented</span></td></tr></tbody></table><p class="jnote">* In PostgreSQL, Repeatable Read also prevents phantoms. Higher levels are safer but cause more waiting, and sometimes a transaction must be retried.</p></div></div><div class="jgrid j2"><div class="jcard "><h4>Defaults and how to set one</h4><ul class="jbul"><li><strong>PostgreSQL</strong> default: Read Committed.</li><li><strong>MySQL (InnoDB)</strong> default: Repeatable Read.</li><li>PostgreSQL never allows dirty reads. "Read Uncommitted" behaves like Read Committed there.</li></ul><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>BEGIN ISOLATION LEVEL REPEATABLE READ;
-- queries here see one steady snapshot
COMMIT;</code></pre></div><p class="jnote">Choose per transaction. Most apps stay on the default and use Serializable only for money-critical logic.</p></div><div class="jcard "><h4>Which level should I use?</h4><ul class="jbul"><li><strong>Read Committed:</strong> fine for most apps, and the usual default.</li><li><strong>Repeatable Read:</strong> when one transaction must see a steady picture, for example a long report.</li><li><strong>Serializable:</strong> money-critical logic. Be ready to <strong>retry</strong> if the database cancels a transaction.</li></ul></div></div>`, '4'),
      block('Locking basics and deadlocks', 'When two transactions want the same row, one waits. When they wait for each other, that is a deadlock.', `<div class="jgrid j2"><div class="jcard "><h4>Locks in one minute</h4><ul class="jbul"><li>When a transaction <strong>changes a row</strong>, it locks that row. Others who want to change it <strong>wait</strong> until it commits or rolls back.</li><li>In PostgreSQL and MySQL (InnoDB) a plain <code>SELECT</code> does not wait and does not block anyone.</li><li>Long transactions hold locks for a long time, which makes other queries look "slow".</li></ul><p class="jsub" style="margin-top:12px">Lock rows on purpose so nobody changes them while you decide:</p><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>BEGIN;
SELECT balance FROM accounts WHERE id = 1 FOR UPDATE;
-- check the balance, then:
UPDATE accounts SET balance = balance - 200 WHERE id = 1;
COMMIT;</code></pre></div></div><div class="jcard "><h4>A deadlock</h4><p class="jsub">Each one holds a row the other needs.</p><div class="jfig"><svg viewBox="0 0 560 214" style="width:100%;max-width:560px;height:auto" role="img" aria-label="Deadlock: A holds row 1 and waits for row 2, B holds row 2 and waits for row 1" font-family="Inter, system-ui, Arial, sans-serif"><line x1="70" y1="58" x2="70" y2="154" stroke="#1e7a4c" stroke-width="2.6"/><line x1="490" y1="58" x2="490" y2="154" stroke="#1e7a4c" stroke-width="2.6"/><line x1="110" y1="58" x2="450" y2="154" stroke="#b8741a" stroke-width="2.4" stroke-dasharray="7 6"/><line x1="450" y1="58" x2="110" y2="154" stroke="#b8741a" stroke-width="2.4" stroke-dasharray="7 6"/><rect x="10" y="14" width="120" height="42" rx="10" fill="#fff" stroke="#0d0d0d" stroke-width="1.7"/><text x="70" y="40" text-anchor="middle" font-size="14" font-weight="700" fill="#0d0d0d">Txn A</text><rect x="430" y="14" width="120" height="42" rx="10" fill="#fff" stroke="#0d0d0d" stroke-width="1.7"/><text x="490" y="40" text-anchor="middle" font-size="14" font-weight="700" fill="#0d0d0d">Txn B</text><rect x="10" y="156" width="120" height="42" rx="10" fill="#f3f3f1" stroke="#0d0d0d" stroke-width="1.7"/><text x="70" y="182" text-anchor="middle" font-size="14" font-weight="600" font-family="ui-monospace, Consolas, monospace" fill="#0d0d0d">row 1</text><rect x="430" y="156" width="120" height="42" rx="10" fill="#f3f3f1" stroke="#0d0d0d" stroke-width="1.7"/><text x="490" y="182" text-anchor="middle" font-size="14" font-weight="600" font-family="ui-monospace, Consolas, monospace" fill="#0d0d0d">row 2</text><text x="80" y="112" font-size="12" font-weight="600" fill="#135238">holds</text><text x="500" y="112" font-size="12" font-weight="600" fill="#135238">holds</text><text x="280" y="84" text-anchor="middle" font-size="12" font-weight="600" fill="#85500f">each waits for the other</text></svg></div><p class="jnote">Neither can ever continue. The database notices the cycle, <strong>cancels one</strong> transaction (the "victim") with an error, and lets the other finish.</p></div></div><div class="jgrid j2"><div class="jcard "><h4>How it unfolds</h4><table class="jtime"><thead><tr><th>#</th><th>Transaction A</th><th>Transaction B</th><th>What happens</th></tr></thead><tbody><tr><td>1</td><td><code>UPDATE … WHERE id = 1</code></td><td></td><td>A locks <strong>row 1</strong>.</td></tr><tr><td>2</td><td></td><td><code>UPDATE … WHERE id = 2</code></td><td>B locks <strong>row 2</strong>.</td></tr><tr><td>3</td><td><code>UPDATE … WHERE id = 2</code></td><td></td><td>A wants row 2, so it waits for B.</td></tr><tr class="hl"><td>4</td><td></td><td><code>UPDATE … WHERE id = 1</code></td><td>B wants row 1, so it waits for A. <strong>Deadlock.</strong></td></tr><tr><td>5</td><td></td><td></td><td>The database rolls one back with "deadlock detected". The other continues.</td></tr></tbody></table></div><div class="jcard "><h4>How to avoid them</h4><ul class="jbul"><li><strong>Same order, always.</strong> If every transaction touches row 1 before row 2, a cycle cannot form.</li><li><strong>Keep transactions short.</strong> No waiting for a user or an API call inside one.</li><li><strong>Lock only what you need.</strong></li><li><strong>Retry.</strong> The victim got an error, so catch it and run the transaction again.</li></ul></div></div>`, '5'),
      block('Normalization: 1NF, 2NF, 3NF', 'Organise tables so each fact is stored once. We improve one messy table, step by step.', `<div class="callout green"><div class="callout-title">One sentence to remember</div><p>Every column must depend on <strong>the key</strong> (1NF), <strong>the whole key</strong> (2NF), and <strong>nothing but the key</strong> (3NF).</p></div><div class="jcard "><h4>Start: a messy table</h4><p class="jsub">Two problems. Several products are packed into one cell, and customer facts are repeated.</p><div class="tv-grid"><div class="tv"><div class="tv-head">orders_raw<small>2 rows</small></div><div class="tv-scroll"><table><thead><tr><th>order_id</th><th>customer</th><th>city</th><th>products</th></tr></thead><tbody><tr><td>101</td><td>Asha</td><td>Pune</td><td><span class="jbad">Pen, Book</span></td></tr><tr><td>102</td><td>Ravi</td><td>Delhi</td><td>Bag</td></tr></tbody></table></div></div></div></div><div class="jgrid j3"><div class="jcard "><h4>1NF: one value per cell</h4><p class="jsub">No lists in a cell, no repeating columns (<code>product1</code>, <code>product2</code>). Each row identifiable.</p><div class="tv"><div class="tv-head">orders<small>3 rows</small></div><div class="tv-scroll"><table><thead><tr><th>order_id</th><th>customer</th><th>city</th><th>product</th></tr></thead><tbody><tr class="hl"><td>101</td><td>Asha</td><td>Pune</td><td>Pen</td></tr><tr class="hl"><td>101</td><td>Asha</td><td>Pune</td><td>Book</td></tr><tr><td>102</td><td>Ravi</td><td>Delhi</td><td>Bag</td></tr></tbody></table></div></div><p class="jnote">Key is <code>(order_id, product)</code>. Asha and Pune are still repeated (amber).</p></div><div class="jcard "><h4>2NF: the whole key</h4><p class="jsub">A column must depend on the <strong>whole</strong> key, not part of it. Here customer and city depend only on <code>order_id</code>, so move them out.</p><div class="tv"><div class="tv-head">orders<small>2 rows</small></div><div class="tv-scroll"><table><thead><tr><th>order_id</th><th>customer</th><th>city</th></tr></thead><tbody><tr><td>101</td><td>Asha</td><td>Pune</td></tr><tr><td>102</td><td>Ravi</td><td>Delhi</td></tr></tbody></table></div></div><div class="tv"><div class="tv-head">order_items<small>3 rows</small></div><div class="tv-scroll"><table><thead><tr><th>order_id</th><th>product</th></tr></thead><tbody><tr><td>101</td><td>Pen</td></tr><tr><td>101</td><td>Book</td></tr><tr><td>102</td><td>Bag</td></tr></tbody></table></div></div><p class="jnote">Only matters when the key has two or more columns.</p></div><div class="jcard "><h4>3NF: nothing but the key</h4><p class="jsub">No column may depend on another <strong>non-key</strong> column. City depends on the customer (<code>order → customer → city</code>), so move it out.</p><div class="tv"><div class="tv-head">customers<small>2 rows</small></div><div class="tv-scroll"><table><thead><tr><th>customer_id</th><th>name</th><th>city</th></tr></thead><tbody><tr><td>1</td><td>Asha</td><td>Pune</td></tr><tr><td>2</td><td>Ravi</td><td>Delhi</td></tr></tbody></table></div></div><div class="tv"><div class="tv-head">orders<small>2 rows</small></div><div class="tv-scroll"><table><thead><tr><th>order_id</th><th>customer_id</th></tr></thead><tbody><tr><td>101</td><td>1</td></tr><tr><td>102</td><td>2</td></tr></tbody></table></div></div><div class="tv"><div class="tv-head">order_items<small>3 rows</small></div><div class="tv-scroll"><table><thead><tr><th>order_id</th><th>product</th></tr></thead><tbody><tr><td>101</td><td>Pen</td></tr><tr><td>101</td><td>Book</td></tr><tr><td>102</td><td>Bag</td></tr></tbody></table></div></div></div></div><div class="jgrid j2"><div class="jcard "><h4>What goes wrong without it</h4><table class="tbl"><thead><tr><th>Problem</th><th>Example</th></tr></thead><tbody><tr><td>Update</td><td>Asha moves to Mumbai. You must change every order row she appears in, and missing one leaves two cities.</td></tr><tr><td>Insert</td><td>You cannot save a new customer until they place an order.</td></tr><tr><td>Delete</td><td>Deleting Ravi's only order also deletes the fact that Ravi exists.</td></tr></tbody></table></div><div class="jcard "><h4>Good to know</h4><ul class="jbul"><li>Most real schemas aim for <strong>3NF</strong>.</li><li>Normal forms go beyond 3NF (BCNF and more), but 1NF to 3NF is what interviews ask.</li><li>Sometimes you <strong>denormalize on purpose</strong> (store a copy) to make reads faster. Do it knowingly and keep the copy updated.</li></ul></div></div>`, '6'),
      block('Constraints and data integrity', 'Rules the database enforces for you, so bad data cannot get in, whatever code is writing.', `<div class="jgrid j2"><div class="jcard "><h4>The constraints</h4><table class="tbl"><thead><tr><th>Constraint</th><th>Rule</th><th>Example</th></tr></thead><tbody><tr><td><code>NOT NULL</code></td><td>A value is required</td><td><code>email</code></td></tr><tr><td><code>UNIQUE</code></td><td>No duplicates</td><td><code>username</code></td></tr><tr><td><code>PRIMARY KEY</code></td><td>Unique and not null, identifies the row</td><td><code>user_id</code></td></tr><tr><td><code>FOREIGN KEY</code></td><td>Must point to a real row</td><td><code>posts.user_id → users</code></td></tr><tr><td><code>CHECK</code></td><td>Your own condition</td><td><code>balance &gt;= 0</code></td></tr><tr><td><code>DEFAULT</code></td><td>Value used when none is given</td><td><code>created_at = now()</code></td></tr></tbody></table></div><div class="jcard "><h4>All of them in one table</h4><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>CREATE TABLE accounts (
  id        BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  owner     VARCHAR(50)   NOT NULL UNIQUE,
  balance   DECIMAL(12,2) NOT NULL DEFAULT 0
                          CHECK (balance &gt;= 0),
  user_id   BIGINT REFERENCES users (user_id)
                          ON DELETE SET NULL
);</code></pre></div><p class="jnote">Try to take 5000 from a balance of 1000 and the <code>CHECK</code> fails, the statement errors, and the transaction rolls back. This is <strong>Consistency</strong> in action.</p></div></div><div class="jgrid j2"><div class="jcard "><h4>Foreign key: what happens on delete?</h4><p class="jsub">Choose with <code>ON DELETE …</code>.</p><table class="tbl"><thead><tr><th>Option</th><th>When the parent row is deleted</th></tr></thead><tbody><tr><td><code>CASCADE</code></td><td>the child rows are deleted too</td></tr><tr><td><code>SET NULL</code></td><td>the child's foreign key becomes NULL</td></tr><tr><td><code>RESTRICT</code> / <code>NO ACTION</code></td><td>the delete is <strong>blocked</strong> (the default)</td></tr></tbody></table></div><div class="jcard "><h4>Why not just validate in the app?</h4><div class="callout green"><div class="callout-title">Last line of defense</div><p>App checks give friendly messages. Constraints guarantee the rule. Other services, scripts, migrations and bugs can all write to the same database, and only the database can stop all of them.</p></div></div></div>`, '7'),
      block('Basic schema design', 'A simple recipe that works for most apps. Example: the mini Instagram.', `<div class="jgrid j2"><div class="jcard "><h4>The recipe</h4><ol class="tv-steps">
        <li><strong>List the things</strong> (entities): users, posts, likes.</li>
        <li><strong>List what you store</strong> about each (columns).</li>
        <li><strong>Give each table a primary key.</strong></li>
        <li><strong>Connect them.</strong> One-to-many: foreign key on the "many" side. Many-to-many: a junction table.</li>
        <li><strong>Normalize</strong> to 3NF. Store each fact once.</li>
        <li><strong>Add constraints</strong>: NOT NULL, UNIQUE, CHECK, foreign keys.</li>
        <li><strong>Add indexes</strong> for the queries you will run (foreign keys first).</li>
      </ol></div><div class="jcard "><h4>The mini Instagram, as SQL</h4><div class="code"><div class="code-bar">SQL</div><pre><code data-sql>CREATE TABLE users (
  user_id    BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  username   VARCHAR(30)  NOT NULL UNIQUE,
  email      VARCHAR(255) NOT NULL UNIQUE,
  created_at TIMESTAMP    NOT NULL DEFAULT now()
);

CREATE TABLE posts (
  post_id    BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  user_id    BIGINT NOT NULL REFERENCES users (user_id)
                    ON DELETE CASCADE,
  caption    TEXT,
  created_at TIMESTAMP NOT NULL DEFAULT now()
);
CREATE INDEX idx_posts_user_id ON posts (user_id);

CREATE TABLE likes (
  user_id    BIGINT NOT NULL REFERENCES users (user_id) ON DELETE CASCADE,
  post_id    BIGINT NOT NULL REFERENCES posts (post_id) ON DELETE CASCADE,
  created_at TIMESTAMP NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, post_id)   -- one like per user per post
);</code></pre></div><p class="jnote"><code>likes</code> is the junction table. Its composite primary key stops a user liking the same post twice.</p></div></div><div class="jgrid j2"><div class="jcard "><h4>Choosing data types</h4><table class="tbl"><thead><tr><th>Data</th><th>Use</th><th>Avoid</th></tr></thead><tbody><tr><td>Money</td><td><code>DECIMAL(12,2)</code></td><td><code>FLOAT</code> (rounding errors)</td></tr><tr><td>Ids</td><td><code>BIGINT</code> identity, or <code>UUID</code></td><td>text ids</td></tr><tr><td>Short text</td><td><code>VARCHAR(n)</code></td><td></td></tr><tr><td>Long text</td><td><code>TEXT</code></td><td></td></tr><tr><td>Date and time</td><td><code>TIMESTAMP</code></td><td>dates stored as text</td></tr><tr><td>Yes / no</td><td><code>BOOLEAN</code></td><td><code>'Y'</code> / <code>'N'</code> text</td></tr></tbody></table></div><div class="jcard "><h4>Common mistakes</h4><ul class="jbul"><li>Storing a list in one column (<code>'101,102,103'</code>). Use a junction table.</li><li>A table with no primary key.</li><li>No foreign keys, so orphan rows appear.</li><li><code>FLOAT</code> for money.</li><li>Storing a value you can calculate (like a like count) without keeping it in sync.</li><li>Forgetting the index on a foreign key.</li></ul></div></div>`, '8'),
      block('Cheat sheet', 'The short answers.', `<div class="jcard"><table class="tbl"><thead><tr><th>Term</th><th>One-line answer</th></tr></thead><tbody><tr><td>Transaction</td><td>A group of statements that succeed or fail together.</td></tr><tr><td>Atomicity</td><td>All or nothing.</td></tr><tr><td>Consistency</td><td>The data always follows its rules.</td></tr><tr><td>Isolation</td><td>Overlapping transactions do not see each other's unfinished work.</td></tr><tr><td>Durability</td><td>Committed data survives a crash.</td></tr><tr><td>Dirty read</td><td>Reading another transaction's uncommitted change.</td></tr><tr><td>Non-repeatable read</td><td>The same row gives a different value on the second read.</td></tr><tr><td>Phantom read</td><td>The same query returns a different set of rows on the second read.</td></tr><tr><td>Deadlock</td><td>Two transactions each wait for a lock the other holds. The database cancels one.</td></tr><tr><td>1NF / 2NF / 3NF</td><td>One value per cell / depends on the whole key / depends on nothing but the key.</td></tr><tr><td>Constraint</td><td>A rule the database enforces (NOT NULL, UNIQUE, PRIMARY KEY, FOREIGN KEY, CHECK).</td></tr></tbody></table></div>`, '9'),
    ],
  });

  Ops.content['sql'] = Ops.h.module({
    id: 'session-3', prefix: 's3', num: 3, title: 'SQL and Databases',
    lead: 'Application data lives in databases. Learn to ask it questions, such as which orders have no payment, safely.',
    tag: ' <span class="tag amber">Highest priority</span>',
    learn: [
      'SELECT, WHERE, ORDER BY, LIMIT',
      'GROUP BY, HAVING, aggregate functions',
      'INNER JOIN, LEFT JOIN and multiple-table joins',
      'Subqueries and Common Table Expressions (CTEs)',
      'INSERT, UPDATE, DELETE',
      'Primary keys, foreign keys and constraints',
      'NULL handling and duplicate records',
      'Indexes, query performance and EXPLAIN ANALYZE',
      'Transactions and ACID basics',
    ],
    subs,
    extra: [
      block('Practice', '', callout('amber', '', 'Write queries that combine customers, orders, payments and monthly revenue.')),
    ],
  });
})();
